local game = game
local task = task
local type = type
local tostring = tostring
local tonumber = tonumber
local ipairs = ipairs
local pcall = pcall

local Players = game:GetService("Players")
local localPlayer = Players.LocalPlayer or Players.PlayerAdded:Wait()
local env = type(getgenv) == "function" and getgenv() or _G

-- DepHub bundled build. Source revision 0.0.94.
-- Generated by tools/bundle.js. Do not edit by hand.
local BUNDLED_SOURCES = {
    ["src/core/anti-afk.lua"] = [[
local Players = game:GetService("Players")
local VirtualUser = game:GetService("VirtualUser")

local AntiAFK = {
    Enabled = false,
    Connection = nil
}

function AntiAFK.Start()
    if AntiAFK.Enabled then return end
    AntiAFK.Enabled = true

    if AntiAFK.Connection then
        pcall(function()
            AntiAFK.Connection:Disconnect()
        end)
    end

    AntiAFK.Connection = Players.LocalPlayer.Idled:Connect(function()
        if not AntiAFK.Enabled then return end
        pcall(function()
            VirtualUser:CaptureController()
            VirtualUser:ClickButton2(Vector2.new(0, 0))
        end)
    end)
end

function AntiAFK.Stop()
    AntiAFK.Enabled = false
    if AntiAFK.Connection then
        pcall(function()
            AntiAFK.Connection:Disconnect()
        end)
        AntiAFK.Connection = nil
    end
end

function AntiAFK.Toggle(state)
    if state then
        AntiAFK.Start()
    else
        AntiAFK.Stop()
    end
end

AntiAFK.Set = AntiAFK.Toggle

return AntiAFK

]],
    ["src/core/dashboard.lua"] = [[
local game = game
local task = task
local type = type
local tostring = tostring
local tonumber = tonumber
local pcall = pcall
local os_clock = os.clock
local math_floor = math.floor
local string_match = string.match

local GetService = game.GetService
local Players = GetService(game, "Players")
local Stats = GetService(game, "Stats")
local RunService = GetService(game, "RunService")

local Dashboard = {}
Dashboard.__index = Dashboard

local sourceBase = ((type(getgenv)=="function" and getgenv() or _G).__DEPHUB or {}).SourceBaseURL or "https://raw.githubusercontent.com/glowpkj/DepHub/main/"
local RELEASES_BASE_URL = sourceBase .. "src/games/updates/"

local function safeCall(callback, fallback)
    local ok, result = pcall(callback)
    if ok then
        return result
    end
    return fallback
end

local function httpGet(url)
    local ok, result = pcall(function()
        return __dephubHttpGet(url)
    end)
    if ok and type(result) == "string" and #result > 0 then
        return true, result
    end
    return false, nil
end

local function getPing()
    return safeCall(function()
        local network = Stats:FindFirstChild("Network")
        local serverStats = network and network:FindFirstChild("ServerStatsItem")
        local ping = serverStats and (serverStats:FindFirstChild("Data Ping") or serverStats:FindFirstChild("Ping"))
        if not ping then
            return nil
        end
        local raw = ping:GetValueString()
        return math_floor((tonumber(string_match(raw, "[%d%.]+")) or 0) + 0.5)
    end, nil)
end

local function detectExecutor()
    return safeCall(function()
        if type(identifyexecutor) ~= "function" then
            return "Unknown"
        end
        local name, version = identifyexecutor()
        if name and version then
            return tostring(name) .. " " .. tostring(version)
        end
        return name and tostring(name) or "Unknown"
    end, "Unknown")
end

local function parseUpdates(source)
    local updates = {}
    if type(source) ~= "string" then
        return updates
    end

    for line in source:gmatch("[^\r\n]+") do
        line = line:gsub("^%s+", ""):gsub("%s+$", "")
        if line ~= "" then
            local version, change = line:match("^([^|]+)|(.+)$")
            if version and change then
                updates[#updates + 1] = {
                    Version = version:gsub("^%s+", ""):gsub("%s+$", ""),
                    Date = "",
                    Changes = {change:gsub("^%s+", ""):gsub("%s+$", "")}
                }
            else
                updates[#updates + 1] = {
                    Version = line,
                    Date = "",
                    Changes = {}
                }
            end
        end
    end

    return updates
end

local function getRecentUpdates(placeId)
    local ok, source = httpGet(RELEASES_BASE_URL .. tostring(placeId) .. ".txt?dephubupdates=" .. tostring(math_floor(os_clock() * 1000000)))
    if not ok then
        return {}, "Unknown"
    end

    local updates = parseUpdates(source)
    return updates, updates[1] and updates[1].Version or "Unknown"
end

function Dashboard.new(options)
    options = options or {}

    local self = setmetatable({}, Dashboard)
    self.Destroyed = false
    self.Started = false
    self.Interval = math.max(tonumber(options.Interval) or 1, 0.25)
    self.ManifestInterval = math.max(tonumber(options.ManifestInterval) or 30, 5)
    self.Executor = detectExecutor()
    self.ScriptVersion = options.ScriptVersion and tostring(options.ScriptVersion) or nil
    self.FPS = 0
    self.Ping = nil
    self.LastUpdate = 0
    self.LastReleaseCheck = 0
    self.Connections = {}
    self.StartedAt = os_clock()
    self.Data = {}
    self.OnUpdate = options.OnUpdate
    self.RecentUpdates = {}
    return self
end

function Dashboard:RefreshUpdates(force)
    local now = os_clock()
    if not force and now - self.LastReleaseCheck < self.ManifestInterval then
        return
    end

    local updates, version = getRecentUpdates(game.PlaceId)
    self.RecentUpdates = updates
    self.ScriptVersion = version
    self.LastReleaseCheck = now
end

function Dashboard:Collect()
    if self.Destroyed then
        return nil
    end

    self:RefreshUpdates(false)

    local playerCount = safeCall(function()
        return #Players:GetPlayers()
    end, 0)

    local maxPlayers = safeCall(function()
        return Players.MaxPlayers
    end, 0)

    local data = {
        Executor = self.Executor,
        Ping = getPing(),
        FPS = self.FPS,
        PlaceId = tostring(game.PlaceId),
        GameId = tostring(game.GameId),
        JobId = tostring(game.JobId),
        GameName = tostring(game.Name),
        ScriptVersion = self.ScriptVersion or "Unknown",
        RecentUpdates = self.RecentUpdates,
        Players = playerCount,
        MaxPlayers = maxPlayers,
        Uptime = math.max(os_clock() - self.StartedAt, 0),
        Timestamp = os_clock()
    }

    self.Ping = data.Ping
    self.LastUpdate = data.Timestamp
    self.Data = data

    if self.OnUpdate then
        pcall(self.OnUpdate, data)
    end

    return data
end

function Dashboard:Start()
    if self.Destroyed or self.Started then
        return not self.Destroyed
    end

    self.Started = true
    self:RefreshUpdates(true)
    self:Collect()

    self.Connections[#self.Connections + 1] = RunService.Heartbeat:Connect(function(deltaTime)
        if deltaTime > 0 then
            local instant = 1 / deltaTime
            self.FPS = math_floor((self.FPS * 0.85) + (instant * 0.15) + 0.5)
        end
    end)

    task.spawn(function()
        while not self.Destroyed do
            task.wait(self.Interval)
            if not self.Destroyed then
                self:Collect()
            end
        end
    end)

    return true
end

function Dashboard:Get()
    return self.Data
end

function Dashboard:GetSnapshot()
    local snapshot = {}
    for key, value in pairs(self.Data) do
        snapshot[key] = value
    end
    return snapshot
end

function Dashboard:Destroy()
    if self.Destroyed then
        return
    end

    self.Destroyed = true
    self.Started = false

    for _, connection in ipairs(self.Connections) do
        pcall(function()
            connection:Disconnect()
        end)
    end

    self.Connections = {}
    self.Data = {}
end

return Dashboard


]],
    ["src/core/demon-ui.lua"] = [[
-- Shared DepHub shell.
--
-- Every game gets the exact same interface: the same library, the same theme,
-- the same size, the same tab/section/control API. The backend of each game is
-- what fills that shell with its own tabs and controls — the shell itself never
-- knows which game it is running and never adds anything game-specific.
--
-- Stable API handed to every backend through env.__DEPHUB.UI:
--   UI:CreateCategory(name, icon)          -- only when a backend wants categories
--   UI:CreateTab(name, category)           -- returns a tab wrapper or nil
--   tab:CreateSection(title, column)       -- "Left" (default) or "Right"
--   section:CreateToggle/Slider/Dropdown/Button/Input/Paragraph(...)
--   UI:Notify(title, message, kind)
--   UI:SetCurrentSea(sea)                  -- category switching, opt-in per backend
--   UI:Destroy()

local DemonUI = {}
DemonUI.__index = DemonUI

-- Window options are shared by every game so the interface is identical
-- everywhere. Changing anything here changes it for all games at once.
local WINDOW_OPTIONS = {
    Title = "DepHub",
    Author = "DepHub",
    Theme = "Monochrome",
    TabPosition = "Side",
    CategoryAlign = "Center",
    ToggleKey = Enum.KeyCode.RightControl,
    Acrylic = true,
    AcrylicBlur = 18,
    Size = UDim2.fromOffset(900, 580),
    ThemeAutoLoad = false,
    SoundsEnabled = true,
    Tooltip = true
}

-- The one category every game has. Backends that want more (for example the
-- Blox Fruits sea categories) create them explicitly through CreateCategory.
local DEFAULT_CATEGORY = "General"

-- The theme module lives in the repository as a normal, editable source file.
-- It is not fetched from a third-party URL and not re-compiled from a blob:
-- it is loaded through the same module path everything else uses, so editing
-- src/core/ui/demon-theme.luau is editing the UI directly.
local THEME_PATHS = {
    "src/core/ui/demon-theme.luau",
    "src/core/ui/demon-theme.lua"
}

local function fetchThemeSource()
    local env = type(getgenv) == "function" and getgenv() or _G
    local resolver = (type(env.__dephubHttpGet) == "function" and env.__dephubHttpGet)
        or (type(env.__DEPHUB_HTTP_GET) == "function" and env.__DEPHUB_HTTP_GET)
        or (type(_G.__dephubHttpGet) == "function" and _G.__dephubHttpGet)
        or (type(_G.__DEPHUB_HTTP_GET) == "function" and _G.__DEPHUB_HTTP_GET)
    local base = (env.__DEPHUB and env.__DEPHUB.SourceBaseURL) or "https://raw.githubusercontent.com/glowpkj/DepHub/main/"
    for _, path in ipairs(THEME_PATHS) do
        if resolver then
            local ok, source = pcall(resolver, base .. path)
            if ok and type(source) == "string" and #source > 0 then return source end
        end
        local ok, source = pcall(function() return __dephubHttpGet(base .. path) end)
        if ok and type(source) == "string" and #source > 0 then return source end
    end
    return nil
end

local cachedTheme = nil

local function loadTheme()
    if cachedTheme then return cachedTheme end
    local source = fetchThemeSource()
    if type(source) ~= "string" or #source == 0 then
        error("Falha ao carregar src/core/ui/demon-theme.luau: nenhuma copia disponivel")
    end
    local chunk, compileError = loadstring(source)
    if not chunk then error("Falha ao compilar demon-theme.luau: " .. tostring(compileError)) end
    local okRun, export = pcall(chunk)
    if not okRun or type(export) ~= "table" or type(export.new) ~= "function" then
        error("demon-theme.luau não retornou uma biblioteca válida: " .. tostring(export))
    end
    cachedTheme = export
    return export
end

local function normalizeSea(sea)
    local value = tostring(sea or "")
    local lower = value:lower()
    if value == "1" or lower:find("sea1") or lower:find("first") or lower == "sea 1" then return "Sea1" end
    if value == "2" or lower:find("sea2") or lower:find("second") or lower == "sea 2" then return "Sea2" end
    if value == "3" or lower:find("sea3") or lower:find("third") or lower == "sea 3" then return "Sea3" end
    return value
end

-- Resolve the category a backend asked for. Backends that pass "All" (or
-- nothing) want the shared default; backends that pass a real category name
-- (a Blox Fruits sea, for example) get exactly that.
local function resolveCategory(category)
    local value = tostring(category or "")
    if value == "" or value == "All" then return DEFAULT_CATEGORY end
    if value == "Sea1" then return "Sea 1" end
    if value == "Sea2" then return "Sea 2" end
    if value == "Sea3" then return "Sea 3" end
    if value == "Sea1,Sea2" or value == "Sea2,Sea1" then return "Sea 1/2" end
    if value == "Sea2,Sea3" or value == "Sea3,Sea2" then return "Sea 2/3" end
    return value
end

function DemonUI.new(options)
    options = options or {}
    local export = loadTheme()
    local library = export.new({
        Title = options.Name or WINDOW_OPTIONS.Title,
        Version = options.Version or "0.0.0",
        Author = WINDOW_OPTIONS.Author,
        Theme = WINDOW_OPTIONS.Theme,
        TabPosition = WINDOW_OPTIONS.TabPosition,
        CategoryAlign = WINDOW_OPTIONS.CategoryAlign,
        ToggleKey = WINDOW_OPTIONS.ToggleKey,
        Acrylic = WINDOW_OPTIONS.Acrylic,
        AcrylicBlur = WINDOW_OPTIONS.AcrylicBlur,
        Size = WINDOW_OPTIONS.Size,
        ThemeAutoLoad = WINDOW_OPTIONS.ThemeAutoLoad,
        SoundsEnabled = WINDOW_OPTIONS.SoundsEnabled,
        Tooltip = WINDOW_OPTIONS.Tooltip
    })
    local self = setmetatable({
        Library = library,
        Tabs = {},
        Categories = {},
        CurrentSea = "Sea1",
        SearchQuery = "",
        Destroyed = false
    }, DemonUI)
    self:CreateCategory(DEFAULT_CATEGORY, "layers")
    return self
end

-- Backends call this to add a category of their own. The shell does not
-- pre-create game categories, so a game can never show another game's tabs.
function DemonUI:CreateCategory(name, icon)
    name = tostring(name or DEFAULT_CATEGORY)
    if self.Categories[name] then return true end
    local ok = pcall(function() self.Library:CreateCategory(name, icon or "layers") end)
    if ok then self.Categories[name] = true end
    return ok
end

function DemonUI:CreateTab(name, category, sea)
    if self.Destroyed then return nil end
    name = tostring(name)
    category = resolveCategory(category)
    if not self.Categories[category] then self:CreateCategory(category) end

    local state = self.Library._STATE
    -- The library indexes pages by tab name alone, so a name is global even
    -- when two categories both want a tab called "Farm". Reuse the tab when the
    -- same name was already created for this same category; otherwise make the
    -- name unique so the library accepts it.
    local existing = self.Tabs[category .. "|" .. name]
    if existing then
        if sea ~= nil then existing.Sea = sea end
        return existing
    end
    local uniqueName = name
    if state and state.ContentPages and state.ContentPages[uniqueName] ~= nil then
        uniqueName = name .. " · " .. category
    end

    local ok, result = pcall(function() self.Library:CreateTab(category, uniqueName) end)
    state = self.Library._STATE
    local tabExists = state and state.ContentPages and state.ContentPages[uniqueName] ~= nil
    if not ok or not tabExists then
        return nil, tostring(result or ("ContentPages[" .. uniqueName .. "] ausente"))
    end
    -- `sea` scopes the tab to one or more seas ("Sea1", "Sea2,Sea3", "All").
    -- nil means the tab is not sea-scoped and is always shown.
    local record = {Adapter = self, Name = uniqueName, DisplayName = name, Category = category, Key = category .. "|" .. name, Control = state.ContentPages[uniqueName], Sections = {}, Visible = true, Sea = sea}
    -- The library owns the tab button; keep a handle so the sea filter can show,
    -- hide, and move it between category lists as the sea changes.
    record.Button = self:_findTabButton(category, uniqueName)
    function record:CreateSection(title, column)
        title = tostring(title or self.Name)
        if self.Sections[title] then return self.Sections[title] end
        local sectionColumn = column or "Left"
        local section = self.Adapter.Library:CreateSection(self.Name, title, nil, true, sectionColumn, "layers")
        local wrapper = {Adapter = self.Adapter, Control = section, Title = title}
        function wrapper:CreateToggle(label, initial, callback)
            return self.Adapter.Library:AddToggle(self.Control, label, initial == true, callback)
        end
        function wrapper:CreateSlider(label, minimum, maximum, initial, callback)
            return self.Adapter.Library:AddSlider(self.Control, label, tonumber(minimum) or 0, tonumber(maximum) or 100, tonumber(initial) or tonumber(minimum) or 0, 0, callback)
        end
        function wrapper:CreateDropdown(label, options, initial, callback)
            local list = {}
            for _, option in ipairs(type(options) == "table" and options or {}) do list[#list + 1] = tostring(option) end
            if #list == 0 then list = {"None"} end
            local index = 1
            for i, option in ipairs(list) do
                if tostring(option) == tostring(initial) then index = i break end
            end
            return self.Adapter.Library:AddDropdown(self.Control, label, list, index, function(_, value)
                if callback then callback(value) end
            end)
        end
        function wrapper:CreateButton(label, callback)
            return self.Adapter.Library:AddButton(self.Control, label, callback)
        end
        function wrapper:CreateInput(label, placeholder, initial, callback)
            local item = {Value = tostring(initial or "")}
            item.Control = self.Adapter.Library:AddTextbox(self.Control, label, tostring(placeholder or initial or ""), function(value)
                item.Value = tostring(value or "")
                if callback then callback(value) end
            end)
            return item
        end
        function wrapper:CreateParagraph(titleText, bodyText)
            return self.Adapter.Library:AddParagraph(self.Control, tostring(titleText or ""), tostring(bodyText or ""))
        end
        self.Sections[title] = wrapper
        return wrapper
    end
    function record:SetVisible(visible)
        self.Visible = visible == true
        self.Adapter:_refreshVisibility()
    end
    self.Tabs[record.Key] = record
    return record
end

-- Category switch used by backends that group tabs by a value (Blox Fruits
-- seas). Categories not managed by the backend are left untouched.
--
-- Visibility is decided per tab: a tab scoped to "Sea1" shows only on Sea 1, a
-- tab scoped to "Sea2,Sea3" shows on Sea 2 and Sea 3, and a tab with no scope is
-- always shown. This is what keeps another sea's features out of the current
-- sea while leaving cross-sea tools (teleport, quests, info) reachable.
function DemonUI:_tabMatchesSea(tab, sea)
    local scope = tab.Sea
    if scope == nil or scope == "" or scope == "All" then return true end
    local value = tostring(scope)
    local lower = value:lower()
    if lower:find("sea1") and sea == "Sea1" then return true end
    if lower:find("sea2") and sea == "Sea2" then return true end
    if lower:find("sea3") and sea == "Sea3" then return true end
    -- A bare sea token without a season word (already normalized values).
    local normalized = normalizeSea(value)
    return normalized == sea
end

-- Locate the tab's button inside its category's TabList. The real library names
-- them "SubTab_<tabName>"; the harness mirror does the same. Returns nil when the
-- library does not expose a list (older stubs), so callers must handle nil.
function DemonUI:_findTabButton(category, tabName)
    local state = self.Library._STATE
    local data = state and state.CategoryButtons and state.CategoryButtons[category]
    local list = data and data.tabList
    if not list then return nil end
    local wanted = "SubTab_" .. tostring(tabName)
    for _, child in ipairs(list:GetChildren()) do
        if child.Name == wanted then return child end
    end
    return nil
end

function DemonUI:_seaCategoryName(sea)
    if sea == "Sea1" then return "Sea 1" end
    if sea == "Sea2" then return "Sea 2" end
    if sea == "Sea3" then return "Sea 3" end
    return nil
end

-- A tab scoped to one or more seas is filed under the current sea's category. The
-- backend builds its tabs before the game reports the sea (the Blox Fruits realm
-- poll is async), so a shared "Sea2,Sea3" tab can start life under a combined
-- "Sea 2/3" category. This moves it to the current sea instead, so the header can
-- show a single sea and the feature stays reachable on that sea. The tab's button
-- is reparented between category tab lists; its page is category-independent, so
-- navigation (SetActiveCategory by category+name) resolves it either way.
function DemonUI:_refileSeaTabs(sea)
    local state = self.Library._STATE
    if type(state) ~= "table" then return end
    local target = self:_seaCategoryName(sea)
    if not target then return end
    if not self.Categories[target] then self:CreateCategory(target) end
    local targetData = state.CategoryButtons and state.CategoryButtons[target]
    local targetList = targetData and targetData.tabList
    if not targetList then return end
    local categoryTabs = state.CategoryTabs or {}
    for _, tab in pairs(self.Tabs) do
        if self:_tabMatchesSea(tab, sea) and tab.Category ~= target and tab.Category ~= DEFAULT_CATEGORY then
            local button = tab.Button
            local fromList = button and button.Parent
            if button and fromList and fromList ~= targetList then
                local fromName = tab.Category
                pcall(function() button.Parent = targetList end)
                -- Keep the library's per-category tab order in step with the move.
                if categoryTabs[fromName] then
                    for i, name in ipairs(categoryTabs[fromName]) do
                        if name == tab.Name then table.remove(categoryTabs[fromName], i) break end
                    end
                end
                categoryTabs[target] = categoryTabs[target] or {}
                local already = false
                for _, name in ipairs(categoryTabs[target]) do if name == tab.Name then already = true break end end
                if not already then categoryTabs[target][#categoryTabs[target] + 1] = tab.Name end
                tab.Category = target
                tab.Key = target .. "|" .. tab.Name
            end
        end
    end
end

function DemonUI:_refreshVisibility()
    if self.Destroyed then return end
    local state = self.Library._STATE
    if type(state) ~= "table" then return end
    local sea = normalizeSea(self.CurrentSea)

    -- Move current-sea features into the current sea's category before deciding
    -- what to show, so nothing is left filed under a hidden combined category.
    pcall(function() self:_refileSeaTabs(sea) end)

    -- Hide the sea categories themselves so the header only shows the one that
    -- belongs to the current sea (plus the shared default). A combined category
    -- ("Sea 1/2", "Sea 2/3") never shows: a feature scoped to several seas is
    -- filed under the current sea instead, so the header stays on a single sea.
    for category, data in pairs(state.CategoryButtons or {}) do
        local visible = category == DEFAULT_CATEGORY
        if category == "Sea 1" then visible = sea == "Sea1" end
        if category == "Sea 2" then visible = sea == "Sea2" end
        if category == "Sea 3" then visible = sea == "Sea3" end
        if category == "Sea 1/2" or category == "Sea 2/3" then visible = false end
        local button = data.button or data
        if button and button:IsA("GuiObject") then button.Visible = visible end
        if data.group and data.group:IsA("GuiObject") then data.group.Visible = visible end
        if data.tabList and data.tabList:IsA("GuiObject") then data.tabList.Visible = visible end
        if data.button and data.button.Parent and data.button.Parent:IsA("GuiObject") then
            data.button.Parent.Visible = visible
        end
    end
    -- Reflow the visible category buttons now that some may be hidden.
    if type(self.Library._layoutCategoryButtons) == "function" then
        pcall(function() self.Library:_layoutCategoryButtons() end)
    end

    -- Hide each tab that is scoped to a different sea. Both its content page and
    -- its tab button are hidden, so a Sea 3 feature never appears while on Sea 1.
    for _, tab in pairs(self.Tabs) do
        local matches = self:_tabMatchesSea(tab, sea)
        tab.Visible = matches
        local page = state.ContentPages and state.ContentPages[tab.Name]
        if page then
            if not matches then page.Visible = false end
        end
        local button = tab.Button
        if button and button.IsA and button:IsA("GuiObject") then button.Visible = matches end
    end

    -- If the tab the library thinks is active just got hidden, fall back to a
    -- tab that is still visible so the player is not left on an empty page.
    local activeCategory = state.ActiveCategory
    local activeTab = state.ActiveTab
    local activeData = activeTab and (self.Tabs[tostring(activeCategory or DEFAULT_CATEGORY) .. "|" .. activeTab] or self.Tabs[activeTab])
    if activeData and not activeData.Visible then
        for _, tab in pairs(self.Tabs) do
            if tab.Visible and tab.Category == (activeCategory or DEFAULT_CATEGORY) then
                pcall(function() self.Library:SetActiveCategory(tab.Category, tab.Name) end)
                break
            end
        end
    end

    -- Re-apply the active search query on top of the sea filter, so switching
    -- seas or refiling tabs never resurrects a hidden search result.
    if self.SearchQuery and self.SearchQuery ~= "" then
        for _, tab in pairs(self.Tabs) do
            if tab.Visible then
                local label = tostring(tab.DisplayName or tab.Name or ""):lower()
                if not label:find(self.SearchQuery, 1, true) then
                    tab.Visible = false
                    local button = tab.Button
                    if button and button.IsA and button:IsA("GuiObject") then button.Visible = false end
                end
            end
        end
    end
end

function DemonUI:SetCurrentSea(sea)
    self.CurrentSea = normalizeSea(sea)
    self:_refreshVisibility()
end

-- Feature search. Filters tab buttons by name so a player can find a feature
-- without knowing which sea or category it lives in. Visibilities combine with
-- the sea filter: a tab shows only when it matches the sea AND the query (an
-- empty query matches everything). The library's own tab list is not rebuilt,
-- only each known tab button's Visible flag is set, so nothing is left orphaned.
function DemonUI:Search(query)
    self.SearchQuery = tostring(query or ""):lower()
    local state = self.Library and self.Library._STATE
    if type(state) ~= "table" then return end
    local sea = normalizeSea(self.CurrentSea)
    for _, tab in pairs(self.Tabs) do
        local matchesSea = self:_tabMatchesSea(tab, sea)
        local label = tostring(tab.DisplayName or tab.Name or ""):lower()
        local matchesQuery = self.SearchQuery == "" or label:find(self.SearchQuery, 1, true) ~= nil
        local visible = matchesSea and matchesQuery
        tab.Visible = visible
        local button = tab.Button
        if button and button.IsA and button:IsA("GuiObject") then button.Visible = visible end
        local page = state.ContentPages and state.ContentPages[tab.Name]
        if page and not visible then page.Visible = false end
    end
end

function DemonUI:Notify(title, message, kind)
    if self.Library and not self.Destroyed then
        return self.Library:Notify(tostring(title or "DepHub"), tostring(message or ""), kind or "info")
    end
end

function DemonUI:Destroy()
    if self.Destroyed then return end
    self.Destroyed = true
    if self.Library then pcall(function() self.Library:Destroy() end) end
    table.clear(self.Tabs)
    table.clear(self.Categories)
end

return DemonUI

]],
    ["src/core/diagnostics.lua"] = [[
-- Shared DepHub live diagnostics console.
--
-- One Debug tab, identical in every game, that behaves like a real terminal:
-- it keeps itself current instead of showing a snapshot, and it listens to
-- both the hub and the game.
--
-- Listeners (read-only; they never modify the game's own scripts):
--   * global log hooks    -- warn/print routed through a capture buffer
--   * ScriptContext.Error -- engine/script errors from the running game
--   * live metrics        -- FPS, ping, memory, uptime, entity counts
--   * structure watch     -- titans/resources entering and leaving
--   * remote sniffer      -- every GET/POST the hub sends, with arguments
--
-- API used by the loader and backends:
--   Diag:SetEnvironment(t)         -- executor/place/version snapshot
--   Diag:Module(name, ok, detail)  -- module load outcome
--   Diag:RegisterModule(name)      -- declare a module before it reports
--   Diag:Probe(label, ok, detail)  -- game-structure probe result
--   Diag:Feature(name, reader)     -- live value, polled for the console
--   Diag:Watch(label, reader)      -- watched value; changes become log lines
--   Diag:Note(text)                -- free-form line
--   Diag:Log(kind, text)           -- capture a log line
--   Diag:Command(name, handler)    -- register a console command
--   Diag:Install(ui)               -- build the live Debug console
--   Diag:Report() / Diag:Copy()    -- whole snapshot as text
--
-- Every collector is pcall-guarded: a probe, feature or hook that throws is
-- shown as an error line instead of taking the hub (or the game) down.
local Diagnostics = {}
Diagnostics.__index = Diagnostics

local MAX_LOG = 400
local REFRESH = 0.5

local function envTable()
    return type(getgenv) == "function" and getgenv() or _G
end

local function safe(...)
    return select(2, pcall(...))
end

-- Capture the environment this chunk was loaded into while we are still at
-- top level. Luau's getfenv() answers for the *calling* function, so a call
-- made later from inside a method can resolve to a different table than the
-- one the chunk actually runs in. Reading it once, here, gives us the real
-- holder for warn/print in every environment (executor globals or a host
-- that ran the chunk under setfenv).
--
-- Note: the probe runs inside its own closure on purpose. Calling getfenv
-- itself as the pcall target would answer for pcall's C frame, not the chunk.
local LOAD_ENV
do
    local ok, captured = pcall(function() return getfenv() end)
    if ok and type(captured) == "table" then LOAD_ENV = captured end
end

local function now()
    return os.clock()
end

local function clockString(seconds)
    seconds = math.max(0, math.floor(seconds or 0))
    return string.format("%02d:%02d:%02d", math.floor(seconds / 3600), math.floor(seconds % 3600 / 60), seconds % 60)
end

function Diagnostics.new()
    local self = setmetatable({
        Environment = {},
        Modules = {}, ModuleOrder = {},
        Probes = {}, ProbeOrder = {},
        Features = {}, FeatureOrder = {},
        Watches = {}, WatchOrder = {}, WatchValues = {},
        Notes = {},
        Logs = {},
        LogPaused = false,
        SniffEnabled = true,
        RemoteLog = {},
        Hooks = {},
        Commands = {},
        StartedAt = now(),
        Metrics = {FPS = 0, Ping = 0, Memory = 0, Uptime = 0, Titans = 0},
        Installed = false,
        Tab = nil,
        RenderTask = nil,
        Destroyed = false
    }, Diagnostics)
    self:_registerBuiltins()
    return self
end

local function pushUnique(list, value)
    if not table.find(list, value) then list[#list + 1] = value end
end

-- ---------------------------------------------------------------------------
-- Data collection
-- ---------------------------------------------------------------------------

function Diagnostics:SetEnvironment(values)
    if type(values) ~= "table" then return end
    for key, value in pairs(values) do self.Environment[tostring(key)] = tostring(value) end
end

function Diagnostics:RegisterModule(name)
    name = tostring(name)
    pushUnique(self.ModuleOrder, name)
    if self.Modules[name] == nil then self.Modules[name] = {Ok = nil, Detail = "pendente"} end
    return name
end

function Diagnostics:Module(name, ok, detail)
    name = tostring(name)
    pushUnique(self.ModuleOrder, name)
    self.Modules[name] = {Ok = ok == true, Detail = detail ~= nil and tostring(detail) or (ok and "ok" or "sem detalhe")}
    self:_addLog("module", (ok and "[OK] " or "[FALHA] ") .. name .. ": " .. self.Modules[name].Detail)
end

function Diagnostics:Probe(label, ok, detail)
    label = tostring(label)
    pushUnique(self.ProbeOrder, label)
    self.Probes[label] = {Ok = ok == true, Detail = detail ~= nil and tostring(detail) or (ok and "ok" or "ausente")}
end

function Diagnostics:Feature(name, reader)
    name = tostring(name)
    pushUnique(self.FeatureOrder, name)
    self.Features[name] = reader
end

-- A watch polls its reader on the console loop and writes a log line whenever
-- the value changes, so structure changes (a titan spawning, a remote leaving)
-- become timestamped events instead of a value you have to stare at.
function Diagnostics:Watch(label, reader)
    label = tostring(label)
    pushUnique(self.WatchOrder, label)
    self.Watches[label] = reader
end

function Diagnostics:Note(text)
    self.Notes[#self.Notes + 1] = tostring(text)
end

function Diagnostics:Command(name, handler)
    self.Commands[tostring(name)] = handler
end

-- ---------------------------------------------------------------------------
-- Log capture + hooks
-- ---------------------------------------------------------------------------

local function stamp()
    return string.format("%6.2f", now() % 100000)
end

function Diagnostics:_addLog(kind, text)
    if self.LogPaused and kind ~= "console" then return end
    self.Logs[#self.Logs + 1] = {Kind = tostring(kind or "log"), Text = tostring(text), T = stamp()}
    while #self.Logs > MAX_LOG do table.remove(self.Logs, 1) end
end

function Diagnostics:Log(kind, text)
    self:_addLog(kind, text)
end

-- Wrap the executor's warn/print so everything the hub *and the game* prints is
-- captured. The originals are always called, so nothing is swallowed.
function Diagnostics:_installLogHooks()
    if self.Hooks.warn or self.Hooks.print then return end
    -- Candidate holders, in priority order: the table the chunk was loaded
    -- into (always correct), the shared executor globals, and the raw _G.
    local holders = {}
    local seen = {}
    local function add(table_)
        if type(table_) == "table" and not seen[table_] then
            seen[table_] = true
            holders[#holders + 1] = table_
        end
    end
    add(LOAD_ENV)
    add(envTable())
    add(_G)
    for _, name in ipairs({"warn", "print"}) do
        -- Hook every holder that currently exposes the function, so a line
        -- emitted by the hub or by the game is captured no matter which table
        -- it resolves through. The first one found is the reference the
        -- wrapper forwards to.
        local original
        for _, holder in ipairs(holders) do
            if type(holder[name]) == "function" then
                original = original or holder[name]
                break
            end
        end
        if original then
            local wrapped = function(...)
                local parts = {}
                for i = 1, select("#", ...) do parts[i] = tostring(select(i, ...)) end
                self:_addLog(name, table.concat(parts, " "))
                return original(...)
            end
            local installed = {}
            for _, holder in ipairs(holders) do
                if type(holder[name]) == "function" then
                    pcall(function() holder[name] = wrapped end)
                    installed[#installed + 1] = holder
                end
            end
            self.Hooks[name] = {Original = original, Holders = installed, Wrapped = wrapped}
        end
    end
    -- ScriptContext.Error reports errors raised by scripts running in this
    -- client, including the game's own. We only listen.
    local ok, scriptContext = pcall(function() return game:GetService("ScriptContext") end)
    if ok and scriptContext and scriptContext.Error and not self.Hooks.ScriptContext then
        local connection = scriptContext.Error:Connect(function(message, stack)
            self:_addLog("erro", tostring(message) .. (stack and ("\n" .. tostring(stack)) or ""))
        end)
        self.Hooks.ScriptContext = connection
    end
end

function Diagnostics:_removeLogHooks()
    local env = envTable()
    local restore = env.restorefunction or _G.restorefunction
    for name, hook in pairs(self.Hooks) do
        if name == "ScriptContext" then
            pcall(function() hook:Disconnect() end)
        elseif type(hook) == "table" and hook.Holders then
            for _, holder in ipairs(hook.Holders) do
                pcall(function() holder[name] = hook.Original end)
            end
        elseif type(hook) == "table" then
            -- Remote sniffer record: undo executor hooks and field patches.
            if hook.Restores and type(restore) == "function" then
                for _, handle in ipairs(hook.Restores) do pcall(restore, handle) end
            end
            for _, patch in ipairs(hook.Fields or {}) do
                pcall(function() rawset(patch.Remote, patch.Name, patch.Original) end)
            end
        end
    end
    self.Hooks = {}
end

-- Wrap a remote so every invocation the hub makes is logged with its arguments.
-- The wrapping is transparent: the original call is forwarded untouched.
--
-- Real Roblox Instances keep their methods on a shared metatable, so a plain
-- field assignment does not override InvokeServer/FireServer. The sniffer
-- therefore prefers an executor's hooking primitive (hookfunction /
-- replaceclosure) when one is present, and only falls back to a field patch
-- for plain-function doubles that accept one.
function Diagnostics:SniffRemote(remote, label)
    if not remote then return end
    label = tostring(label)
    local key = "remote:" .. label
    if self.Hooks[key] then return end

    local env = envTable()
    local hook = env.hookfunction or _G.hookfunction
    local restore = env.restorefunction or _G.restorefunction
    local record = {Restores = {}, Fields = {}}
    self.Hooks[key] = record

    -- Reading a method that does not exist on the Instance's type raises
    -- ("FireServer is not a valid member of RemoteFunction"), so every method
    -- read goes through pcall. A RemoteFunction exposes InvokeServer and a
    -- RemoteEvent exposes FireServer; whichever is absent simply yields nil.
    for _, name in ipairs({"InvokeServer", "FireServer"}) do
        local okRead, method = pcall(function() return remote[name] end)
        if okRead and type(method) == "function" then
            local verb = name == "InvokeServer" and "GET " or "POST "
            local wrapped = function(instance, ...)
                self:_addLog("remote", verb .. label .. "(" .. self:_fmtArgs(...) .. ")")
                return method(instance, ...)
            end
            if type(hook) == "function" then
                -- Executor hooking: swap the closure and keep the handle for
                -- restorefunction on teardown.
                local handle
                local ok = pcall(function() handle = hook(method, wrapped) end)
                if ok and handle ~= nil then
                    record.Restores[#record.Restores + 1] = handle
                else
                    self:_addLog("remote", "nao foi possivel hookar " .. name .. " de " .. label)
                end
            elseif rawget(remote, name) == method then
                -- Plain-function double: patch the own field only, and only
                -- when no metatable shadows it.
                record.Fields[#record.Fields + 1] = {Remote = remote, Name = name, Original = method}
                pcall(function() rawset(remote, name, wrapped) end)
            end
        end
    end
    if type(restore) ~= "function" then record.Restores = nil end
end

function Diagnostics:_fmtArgs(...)
    local parts = {}
    for i = 1, select("#", ...) do
        local value = select(i, ...)
        local kind = type(value)
        if kind == "string" or kind == "number" or kind == "boolean" then
            parts[i] = tostring(value)
        elseif typeof(value) == "Instance" then
            parts[i] = tostring(value.ClassName) .. ":" .. tostring(value.Name)
        elseif typeof(value) == "Vector3" then
            parts[i] = string.format("(%.1f,%.1f,%.1f)", value.X, value.Y, value.Z)
        else
            parts[i] = kind
        end
    end
    return table.concat(parts, ", ")
end

-- ---------------------------------------------------------------------------
-- Metrics
-- ---------------------------------------------------------------------------

-- Resolve a child by name without raising when the member is absent. A raw
-- index like stats.FrameStats throws on executors where the member is not
-- exposed, so every optional read goes through FindFirstChild.
local function child(object, name)
    if not object then return nil end
    local ok, found = pcall(function() return object:FindFirstChild(name) end)
    return ok and found or nil
end

function Diagnostics:_collectMetrics()
    local metrics = self.Metrics
    local okStats, stats = pcall(function() return game:GetService("Stats") end)

    -- FPS: executors expose FrameStats.FrameRate differently. It may be a value
    -- object read via GetValue() or .Value, and some runtimes keep it under
    -- RenderStats instead. Try each route, then fall back to the physics frame
    -- rate the engine reports, so the metric is never stuck at 0 -- and this
    -- runs even when Stats is unavailable.
    local fps
    if okStats and stats then
        local frame = child(stats, "FrameStats") or child(stats, "RenderStats")
        if frame then
            local rate = child(frame, "FrameRate")
            if rate then
                fps = safe(function() return rate:GetValue() end)
                if type(fps) ~= "number" then fps = safe(function() return rate.Value end) end
            end
        end
    end
    if type(fps) ~= "number" then
        fps = safe(function() return workspace:GetRealPhysicsFPS() end)
    end
    if type(fps) == "number" and fps > 0 then metrics.FPS = fps end

    if okStats and stats then
        local network = child(stats, "Network")
        local serverStats = network and child(network, "ServerStatsItem")
        local pingItem = serverStats and child(serverStats, "Data Ping")
        if pingItem then
            local ping = safe(function() return pingItem:GetValue() end)
            if type(ping) ~= "number" then ping = safe(function() return pingItem.Value end) end
            if type(ping) == "number" then metrics.Ping = ping end
        end
        local memory = safe(function() return stats:GetTotalMemoryUsageMb() end)
        if type(memory) == "number" then metrics.Memory = memory end
    end
    metrics.Uptime = now() - self.StartedAt

    -- Entity counts come from whatever the active backend opted to watch; a
    -- generic fallback keeps the console useful before a backend reports.
    local okWorkspace, ws = pcall(function() return game:GetService("Workspace") end)
    if okWorkspace and ws then
        local titans = child(ws, "Titans")
        local count = titans and safe(function() return #titans:GetChildren() end)
        if type(count) == "number" then metrics.Titans = count end
    end
    return metrics
end

function Diagnostics:_pollWatches()
    if self.Destroyed then return end
    for _, label in ipairs(self.WatchOrder) do
        local reader = self.Watches[label]
        if type(reader) == "function" then
            local ok, value = pcall(reader)
            local text = ok and tostring(value) or ("ERRO: " .. tostring(value))
            if self.WatchValues[label] ~= text then
                if self.WatchValues[label] ~= nil then self:_addLog("watch", label .. ": " .. self.WatchValues[label] .. " -> " .. text) end
                self.WatchValues[label] = text
            end
        end
    end
end

-- ---------------------------------------------------------------------------
-- Built-in console commands
-- ---------------------------------------------------------------------------

function Diagnostics:_registerBuiltins()
    self:Command("help", function() return "comandos: " .. self:_commandList() end)
    self:Command("clear", function() self.Logs = {}; return "log limpo" end)
    self:Command("pause", function() self.LogPaused = true; return "log pausado" end)
    self:Command("resume", function() self.LogPaused = false; return "log retomado" end)
    self:Command("report", function() return "relatorio completo: use o botao Copiar relatorio" end)
    self:Command("modules", function()
        local parts = {}
        for _, name in ipairs(self.ModuleOrder) do
            local record = self.Modules[name]
            parts[#parts + 1] = (record and (record.Ok == true and "ok " or record.Ok == false and "FALHA " or "? ") or "? ") .. name
        end
        return table.concat(parts, " | ")
    end)
    self:Command("probes", function()
        local parts = {}
        for _, label in ipairs(self.ProbeOrder) do
            local record = self.Probes[label]
            if record then parts[#parts + 1] = label .. "=" .. tostring(record.Ok and "ok" or "ausente") end
        end
        return table.concat(parts, " | ")
    end)
    self:Command("features", function()
        local parts = {}
        for _, name in ipairs(self.FeatureOrder) do
            local reader = self.Features[name]
            if type(reader) == "function" then
                local ok, value = pcall(reader)
                parts[#parts + 1] = name .. "=" .. (ok and tostring(value) or "ERRO")
            end
        end
        return table.concat(parts, " | ")
    end)
    self:Command("sniff", function(argument)
        if argument == "on" then self.SniffEnabled = true return "sniff de remotes ligado"
        elseif argument == "off" then self.SniffEnabled = false return "sniff de remotes desligado" end
        return "uso: sniff on|off (atual: " .. tostring(self.SniffEnabled) .. ")"
    end)
    self:Command("env", function()
        local parts = {}
        for key, value in pairs(self.Environment) do parts[#parts + 1] = key .. "=" .. tostring(value) end
        table.sort(parts)
        return table.concat(parts, " | ")
    end)
    self:Command("metrics", function()
        local metrics = self:_collectMetrics()
        return string.format("fps=%.0f ping=%.0fms memoria=%.1fMB uptime=%s titans=%d",
            metrics.FPS, metrics.Ping, metrics.Memory, clockString(metrics.Uptime), metrics.Titans)
    end)
end

function Diagnostics:_commandList()
    local names = {}
    for name in pairs(self.Commands) do names[#names + 1] = name end
    table.sort(names)
    return table.concat(names, ", ")
end

function Diagnostics:RunCommand(text)
    text = tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if text == "" then return "" end
    local name, argument = text:match("^(%S+)%s*(.*)$")
    self:_addLog("cmd", "> " .. text)
    local handler = self.Commands[name]
    if not handler then
        local message = "comando desconhecido: " .. name .. " (" .. self:_commandList() .. ")"
        self:_addLog("console", message)
        return message
    end
    local ok, result = pcall(handler, argument ~= "" and argument or nil)
    local message = ok and tostring(result or "ok") or ("erro: " .. tostring(result))
    self:_addLog("console", message)
    return message
end

-- ---------------------------------------------------------------------------
-- Rendering
-- ---------------------------------------------------------------------------

local function statusMark(ok)
    if ok == true then return "[OK]" end
    if ok == false then return "[FALHA]" end
    return "[?]"
end

function Diagnostics:MetricsLine()
    local metrics = self:_collectMetrics()
    return string.format("FPS %3.0f | ping %3.0fms | mem %.0fMB | uptime %s | titans %d",
        metrics.FPS, metrics.Ping, metrics.Memory, clockString(metrics.Uptime), metrics.Titans)
end

function Diagnostics:Report()
    if self.Destroyed then return "diagnostico encerrado" end
    local ok, text = pcall(function() return self:_render() end)
    return ok and text or ("DepHub diagnostico: falha ao montar o relatorio: " .. tostring(text))
end

function Diagnostics:_render()
    local lines = {}
    lines[#lines + 1] = "===== DepHub console ====="
    lines[#lines + 1] = "modulo ativo: " .. tostring((envTable().__DEPHUB or {}).Mode or "?")
    lines[#lines + 1] = self:MetricsLine()
    lines[#lines + 1] = ""

    lines[#lines + 1] = "-- Ambiente --"
    local envKeys = {}
    for key in pairs(self.Environment) do envKeys[#envKeys + 1] = key end
    table.sort(envKeys)
    for _, key in ipairs(envKeys) do lines[#lines + 1] = key .. ": " .. self.Environment[key] end
    lines[#lines + 1] = ""

    lines[#lines + 1] = "-- Modulos --"
    for _, name in ipairs(self.ModuleOrder) do
        local record = self.Modules[name]
        if record then lines[#lines + 1] = statusMark(record.Ok) .. " " .. name .. ": " .. tostring(record.Detail) end
    end
    lines[#lines + 1] = ""

    lines[#lines + 1] = "-- Estrutura do jogo --"
    for _, label in ipairs(self.ProbeOrder) do
        local record = self.Probes[label]
        if record then lines[#lines + 1] = statusMark(record.Ok) .. " " .. label .. ": " .. tostring(record.Detail) end
    end
    lines[#lines + 1] = ""

    lines[#lines + 1] = "-- Estado das features (ao vivo) --"
    for _, name in ipairs(self.FeatureOrder) do
        local reader = self.Features[name]
        if type(reader) == "function" then
            local ok, value = pcall(reader)
            lines[#lines + 1] = name .. ": " .. (ok and tostring(value) or ("ERRO DE LEITURA: " .. tostring(value)))
        end
    end
    lines[#lines + 1] = ""

    if #self.WatchOrder > 0 then
        lines[#lines + 1] = "-- Observados --"
        for _, label in ipairs(self.WatchOrder) do lines[#lines + 1] = label .. ": " .. tostring(self.WatchValues[label] or "?") end
        lines[#lines + 1] = ""
    end

    if #self.Notes > 0 then
        lines[#lines + 1] = "-- Notas --"
        for _, note in ipairs(self.Notes) do lines[#lines + 1] = note end
        lines[#lines + 1] = ""
    end

    lines[#lines + 1] = "-- Log (" .. tostring(#self.Logs) .. " de " .. tostring(MAX_LOG) .. ") --"
    for _, entry in ipairs(self.Logs) do lines[#lines + 1] = "[" .. entry.T .. "][" .. entry.Kind .. "] " .. entry.Text end
    return table.concat(lines, "\n")
end

function Diagnostics:LogText()
    local lines = {}
    for _, entry in ipairs(self.Logs) do lines[#lines + 1] = "[" .. entry.T .. "][" .. entry.Kind .. "] " .. entry.Text end
    return table.concat(lines, "\n")
end

function Diagnostics:Summary()
    local okM, failM, pendM = 0, 0, 0
    for _, name in ipairs(self.ModuleOrder) do
        local record = self.Modules[name]
        if record then
            if record.Ok == true then okM = okM + 1
            elseif record.Ok == false then failM = failM + 1
            else pendM = pendM + 1 end
        end
    end
    local okP, failP = 0, 0
    for _, label in ipairs(self.ProbeOrder) do
        local record = self.Probes[label]
        if record then
            if record.Ok == true then okP = okP + 1 else failP = failP + 1 end
        end
    end
    return string.format("modulos %d ok / %d falha / %d pendente | estrutura %d ok / %d ausente | features %d | log %d",
        okM, failM, pendM, okP, failP, #self.FeatureOrder, #self.Logs)
end

function Diagnostics:Copy()
    local text = self:Report()
    local env = envTable()
    local copied = false
    for _, name in ipairs({"setclipboard", "toclipboard", "Clipboard"}) do
        local fn = (env and env[name]) or _G[name]
        if type(fn) == "function" then
            local ok = pcall(fn, text)
            if ok then copied = true break end
        end
    end
    pcall(print, text)
    return copied, text
end

-- ---------------------------------------------------------------------------
-- Live console UI
-- ---------------------------------------------------------------------------

function Diagnostics:_refreshViews()
    if self.Destroyed then return end
    if self.MetricsParagraph then pcall(function() self.MetricsParagraph:Set(nil, self:MetricsLine()) end) end
    if self.ReportParagraph then pcall(function() self.ReportParagraph:Set(nil, self:Report()) end) end
    if self.LogParagraph then pcall(function() self.LogParagraph:Set(nil, self:LogText()) end) end
end

function Diagnostics:Install(ui)
    if self.Installed or type(ui) ~= "table" or type(ui.CreateTab) ~= "function" then return false end
    local tab = ui:CreateTab("Debug", "All")
    if not tab then return false end
    self.Tab = tab
    self.UI = ui

    local live = tab:CreateSection("Ao vivo", "Left")
    if live then
        self.MetricsParagraph = live:CreateParagraph("Metricas", self:MetricsLine())
        if type(self.MetricsParagraph.Set) ~= "function" then self.MetricsParagraph = nil end
        self.ReportParagraph = live:CreateParagraph("Estado", self:Report())
        if type(self.ReportParagraph.Set) ~= "function" then self.ReportParagraph = nil end
    end

    local controls = tab:CreateSection("Controles", "Left")
    if controls then
        self.LogParagraph = controls:CreateParagraph("Log", self:LogText())
        if type(self.LogParagraph.Set) ~= "function" then self.LogParagraph = nil end
        controls:CreateToggle("Sniff de remotes", self.SniffEnabled, function(value) self.SniffEnabled = value == true end)
        controls:CreateToggle("Pausar log", false, function(value) self.LogPaused = value == true end)
        controls:CreateButton("Limpar log", function() self.Logs = {}; self:_refreshViews() end)
        controls:CreateButton("Copiar relatorio (clipboard + console)", function()
            local copied = self:Copy()
            if type(ui.Notify) == "function" then
                ui:Notify("Debug", copied and "Relatorio copiado." or "Relatorio enviado ao console (clipboard indisponivel).")
            end
            self:_refreshViews()
        end)
    end

    local terminal = tab:CreateSection("Terminal", "Right")
    if terminal then
        self.CommandInput = terminal:CreateInput("Comando", "digite e clique Executar (help)", "", function() end)
        terminal:CreateButton("Executar", function()
            local value = self.CommandInput and self.CommandInput.Value or ""
            self:RunCommand(value)
            if self.CommandInput then pcall(function() self.CommandInput.Control:Set("") end) end
            self:_refreshViews()
        end)
        terminal:CreateParagraph("Comandos", self:_commandList())
    end

    self.Installed = true
    self:_installLogHooks()
    -- A single refresh loop keeps every view current; it stops with Destroy.
    self.RenderTask = task.spawn(function()
        while not self.Destroyed do
            task.wait(REFRESH)
            if self.Destroyed then return end
            local ok, err = pcall(function()
                self:_pollWatches()
                self:_refreshViews()
            end)
            if not ok then self:_addLog("console", "loop: " .. tostring(err)) end
        end
    end)
    self:_addLog("console", "console de debug iniciado")
    return true
end

function Diagnostics:Destroy()
    if self.Destroyed then return end
    self.Destroyed = true
    self:Uninstall()
end

-- Detach the UI tab and the log hooks while keeping the collector alive, so the
-- data keeps accumulating and Install can bring the tab back later. Destroy
-- builds on this and additionally marks the collector as gone.
function Diagnostics:Uninstall()
    if self.RenderTask then pcall(task.cancel, self.RenderTask); self.RenderTask = nil end
    self:_removeLogHooks()
    self.Installed = false
    self.Tab = nil
    self.UI = nil
    self.MetricsParagraph = nil
    self.ReportParagraph = nil
    self.LogParagraph = nil
    self.CommandInput = nil
end

return Diagnostics

]],
    ["src/core/health-monitor.lua"] = [[
local task = task
local type = type
local tostring = tostring
local pcall = pcall
local os_clock = os.clock

local HealthMonitor = {}
HealthMonitor.__index = HealthMonitor

function HealthMonitor.new(options)
    options = options or {}

    local self = setmetatable({}, HealthMonitor)
    self.Destroyed = false
    self.Started = false
    self.Interval = math.max(tonumber(options.Interval) or 2, 0.25)
    self.MaxErrors = tonumber(options.MaxErrors) or 5
    self.Checks = {}
    self.Results = {}
    self.ErrorCount = 0
    self.LastError = nil
    self.Status = "Healthy"
    self.StartedAt = os_clock()
    self.OnChanged = options.OnChanged
    return self
end

function HealthMonitor:Register(name, callback)
    if self.Destroyed or type(name) ~= "string" or type(callback) ~= "function" then
        return false
    end

    self.Checks[name] = {
        Callback = callback,
        Errors = 0,
        Failures = 0,
        LastRun = 0,
        LastSuccess = 0,
        LastError = nil,
        Healthy = true
    }

    return true
end

-- A check that returns false is a normal negative report; only a raised error is a
-- fault. Conflating the two made a legitimately-false check look permanently
-- Unhealthy once it crossed MaxErrors.
function HealthMonitor:RunCheck(name, check)
    local ok, result = pcall(check.Callback, check)
    check.LastRun = os_clock()

    if not ok then
        check.Errors = check.Errors + 1
        check.LastError = tostring(result)
        check.Healthy = false
        self.ErrorCount = self.ErrorCount + 1
        self.LastError = check.LastError
        self.Results[name] = false
        return false
    end

    check.Errors = 0
    check.LastError = nil
    if result == false then
        check.Failures = check.Failures + 1
        check.Healthy = false
    else
        check.Failures = 0
        check.Healthy = true
        check.LastSuccess = os_clock()
    end
    self.Results[name] = check.Healthy
    return check.Healthy
end

function HealthMonitor:Evaluate()
    if self.Destroyed then
        self.Status = "Destroyed"
        return self.Status
    end

    local unhealthy = 0
    local registered = 0

    for name, check in pairs(self.Checks) do
        registered = registered + 1
        if not self:RunCheck(name, check) then
            unhealthy = unhealthy + 1
        end
    end

    if registered == 0 then
        self.Status = "Healthy"
    elseif unhealthy == 0 then
        self.Status = "Healthy"
    elseif unhealthy < registered then
        self.Status = "Degraded"
    else
        self.Status = "Unhealthy"
    end

    if self.OnChanged then
        pcall(self.OnChanged, self.Status, self.Results)
    end

    return self.Status
end

function HealthMonitor:Start()
    if self.Destroyed then
        return false
    end

    if self.Started then
        return true
    end

    self.Started = true

    task.spawn(function()
        while not self.Destroyed do
            self:Evaluate()
            -- Jitter the evaluation cadence so the health loop is not perfectly periodic.
            task.wait(self.Interval * (1 + (math.random() * 2 - 1) * 0.15))
        end
    end)

    return true
end

function HealthMonitor:GetSnapshot()
    local checks = {}

    for name, check in pairs(self.Checks) do
        checks[name] = {
            Healthy = check.Healthy,
            Errors = check.Errors,
            Failures = check.Failures,
            LastError = check.LastError,
            LastRun = check.LastRun,
            LastSuccess = check.LastSuccess
        }
    end

    return {
        Status = self.Status,
        ErrorCount = self.ErrorCount,
        LastError = self.LastError,
        Uptime = math.max(os_clock() - self.StartedAt, 0),
        Checks = checks
    }
end

function HealthMonitor:Destroy()
    if self.Destroyed then
        return
    end

    self.Destroyed = true
    self.Started = false
    self.Checks = {}
    self.Results = {}
    self.Status = "Destroyed"
end

return HealthMonitor

]],
    ["src/core/runtime.lua"] = [[
local type = type
local tostring = tostring
local pcall = pcall
local tonumber = tonumber
local pairs = pairs
local os_clock = os.clock

local Runtime = {}
Runtime.__index = Runtime

function Runtime.new(options)
    options = options or {}

    local Scheduler = options.Scheduler
    local HealthMonitor = options.HealthMonitor
    local Dashboard = options.Dashboard

    local self = setmetatable({}, Runtime)
    self.Destroyed = false
    self.Started = false
    self.StartedAt = os_clock()
    self.ErrorCount = 0
    self.LastError = nil
    self.Health = "Healthy"
    self.Events = {}
    local schedulerOptions = {}
    local providedSchedulerOptions = options.SchedulerOptions
    if type(providedSchedulerOptions) == "table" then
        for key, value in pairs(providedSchedulerOptions) do schedulerOptions[key] = value end
    end
    local previousOnError = schedulerOptions.OnError
    schedulerOptions.OnError = function(state, message)
        self.ErrorCount = self.ErrorCount + 1
        self.LastError = message
        self:Emit("TaskError", state, message)
        if type(previousOnError) == "function" then pcall(previousOnError, state, message) end
    end
    self.Scheduler = type(Scheduler) == "table" and Scheduler.new(schedulerOptions) or nil
    self.HealthMonitor = type(HealthMonitor) == "table" and HealthMonitor.new(options.HealthOptions or {}) or nil
    self.Dashboard = type(Dashboard) == "table" and Dashboard.new(options.DashboardOptions or {}) or nil
    return self
end

function Runtime:On(name, callback)
    if self.Destroyed or type(name) ~= "string" or type(callback) ~= "function" then
        return function() end
    end

    local listeners = self.Events[name]
    if not listeners then
        listeners = {}
        self.Events[name] = listeners
    end

    local connection = {Connected = true, Callback = callback}
    listeners[connection] = true

    return function()
        if not connection.Connected then
            return
        end
        connection.Connected = false
        listeners[connection] = nil
    end
end

function Runtime:Emit(name, ...)
    if self.Destroyed then
        return
    end

    local listeners = self.Events[name]
    if not listeners then
        return
    end

    for connection in pairs(listeners) do
        if connection.Connected then
            pcall(connection.Callback, ...)
        end
    end
end

function Runtime:Register(name, callback, options)
    if self.Destroyed or not self.Scheduler then
        return nil
    end

    local state = self.Scheduler:Register(name, callback, options)
    if state then
        self:Emit("TaskRegistered", state)
    end
    return state
end

function Runtime:SetEnabled(name, enabled)
    if self.Destroyed or not self.Scheduler then
        return false
    end
    return self.Scheduler:SetEnabled(name, enabled)
end

function Runtime:IsEnabled(name)
    return self.Scheduler ~= nil and self.Scheduler:Get(name) ~= nil and self.Scheduler:Get(name).Enabled == true
end

function Runtime:GetTask(name)
    if not self.Scheduler then
        return nil
    end
    return self.Scheduler:Get(name)
end

function Runtime:Start()
    if self.Destroyed then
        return false
    end

    if self.Started then
        return true
    end

    self.Started = true
    self.StartedAt = os_clock()

    if self.Dashboard then
        self.Dashboard:Start()
    end

    if self.HealthMonitor then
        self.HealthMonitor:Start()
    end

    if self.Scheduler then
        self.Scheduler:Start()
    end

    self:Emit("Started")
    return true
end

function Runtime:GetSnapshot()
    local schedulerSnapshot = self.Scheduler and self.Scheduler:GetSnapshot() or {}
    local healthSnapshot = self.HealthMonitor and self.HealthMonitor:GetSnapshot() or {Status = "Unavailable"}
    local dashboardSnapshot = self.Dashboard and self.Dashboard:GetSnapshot() or {}

    self.Health = healthSnapshot.Status or "Unknown"

    return {
        Health = self.Health,
        Started = self.Started,
        StartedAt = self.StartedAt,
        Uptime = math.max(os_clock() - self.StartedAt, 0),
        ErrorCount = self.ErrorCount,
        LastError = self.LastError,
        Tasks = schedulerSnapshot,
        HealthMonitor = healthSnapshot,
        Dashboard = dashboardSnapshot
    }
end

function Runtime:Destroy()
    if self.Destroyed then
        return
    end

    self.Destroyed = true
    self.Started = false

    if self.Scheduler then
        pcall(self.Scheduler.Destroy, self.Scheduler)
    end

    if self.HealthMonitor then
        pcall(self.HealthMonitor.Destroy, self.HealthMonitor)
    end

    if self.Dashboard then
        pcall(self.Dashboard.Destroy, self.Dashboard)
    end

    self.Scheduler = nil
    self.HealthMonitor = nil
    self.Dashboard = nil
    self.Events = {}
    self.Health = "Destroyed"
end

return Runtime

]],
    ["src/core/scheduler.lua"] = [[
local task = task
local type = type
local tostring = tostring
local pcall = pcall
local os_clock = os.clock

local Scheduler = {}
Scheduler.__index = Scheduler

function Scheduler.new(options)
    options = options or {}

    local self = setmetatable({}, Scheduler)
    self.Tasks = {}
    self.Order = {}
    self.Destroyed = false
    self.Started = false
    self.NextId = 0
    self.DefaultInterval = tonumber(options.DefaultInterval) or 0.1
    self.MaxErrors = tonumber(options.MaxErrors) or 5
    self.OnError = type(options.OnError) == "function" and options.OnError or nil
    return self
end

-- Re-registering an existing name must not silently keep the stale callback:
-- backends re-register tasks after respawns with fresh upvalues. Swap the body in
-- place, bump the version (which retires the current thread) and restart if live.
function Scheduler:Register(name, callback, options)
    if self.Destroyed or type(name) ~= "string" or type(callback) ~= "function" then
        return nil
    end

    local existing = self.Tasks[name]
    if existing then
        existing.Callback = callback
        existing.Version = existing.Version + 1
        existing.Started = false
        if options then
            if options.Interval ~= nil then existing.Interval = math.max(tonumber(options.Interval) or existing.Interval, 0.01) end
            if options.Priority ~= nil then existing.Priority = tonumber(options.Priority) or existing.Priority end
            if options.Enabled ~= nil then existing.Enabled = options.Enabled ~= false end
        end
        if self.Started and existing.Enabled then
            self:StartTask(existing)
        end
        return existing
    end

    options = options or {}
    self.NextId = self.NextId + 1

    local state = {
        Id = self.NextId,
        Name = name,
        Callback = callback,
        Interval = math.max(tonumber(options.Interval) or self.DefaultInterval, 0.01),
        Priority = tonumber(options.Priority) or 0,
        Enabled = options.Enabled ~= false,
        Running = false,
        Errors = 0,
        LastError = nil,
        LastRun = 0,
        LastSuccess = 0,
        Started = false,
        RunningVersion = nil,
        Version = 0,
        Destroyed = false
    }

    self.Tasks[name] = state
    self.Order[#self.Order + 1] = state

    if self.Started and state.Enabled then
        self:StartTask(state)
    end

    return state
end

function Scheduler:SetEnabled(name, enabled)
    local state = self.Tasks[name]
    if not state or self.Destroyed then
        return false
    end

    state.Enabled = enabled == true
    state.Version = state.Version + 1
    state.RunningVersion = nil

    if state.Enabled and self.Started then
        self:StartTask(state)
    end

    return true
end

function Scheduler:Run(state)
    if self.Destroyed or state.Destroyed or not state.Enabled or state.Running then
        return false
    end

    state.Running = true
    state.LastRun = os_clock()

    local ok, err = pcall(state.Callback, state)
    state.Running = false

    if ok then
        state.Errors = 0
        state.LastError = nil
        state.LastSuccess = os_clock()
        return true
    end

    state.Errors = state.Errors + 1
    state.LastError = tostring(err)

    if state.Errors >= self.MaxErrors then
        state.Enabled = false
    end

    if self.OnError then
        pcall(self.OnError, state, state.LastError)
    end

    return false
end

-- A task can have at most one live thread per Version. The old guard
-- (`state.Started and state.Enabled`) skipped restarting when the previous thread
-- was still parked in task.wait, leaving an enabled task with no runner.
function Scheduler:StartTask(state)
    if self.Destroyed or state.Destroyed then
        return
    end

    if state.RunningVersion == state.Version and state.Started then
        return
    end

    state.Started = true
    local version = state.Version
    state.RunningVersion = version

    task.spawn(function()
        while not self.Destroyed and not state.Destroyed and state.Version == version do
            if state.Enabled then
                self:Run(state)
            end
            task.wait(state.Interval)
        end
        if state.RunningVersion == version then
            state.Started = false
            state.RunningVersion = nil
        end
    end)
end

function Scheduler:Start()
    if self.Destroyed then
        return false
    end

    if self.Started then
        return true
    end

    self.Started = true

    table.sort(self.Order, function(a, b)
        return a.Priority > b.Priority
    end)

    for _, state in ipairs(self.Order) do
        if state.Enabled then
            self:StartTask(state)
        end
    end

    return true
end

function Scheduler:Stop(name)
    local state = self.Tasks[name]
    if not state then
        return false
    end

    state.Enabled = false
    state.Version = state.Version + 1
    state.RunningVersion = nil
    return true
end

function Scheduler:Get(name)
    return self.Tasks[name]
end

function Scheduler:GetSnapshot()
    local result = {}

    for _, state in ipairs(self.Order) do
        result[#result + 1] = {
            Name = state.Name,
            Enabled = state.Enabled,
            Running = state.Running,
            Errors = state.Errors,
            LastError = state.LastError,
            LastRun = state.LastRun,
            LastSuccess = state.LastSuccess,
            Priority = state.Priority,
            Interval = state.Interval
        }
    end

    return result
end

function Scheduler:Destroy()
    if self.Destroyed then
        return
    end

    self.Destroyed = true

    for _, state in ipairs(self.Order) do
        state.Destroyed = true
        state.Enabled = false
        state.Version = state.Version + 1
        state.RunningVersion = nil
    end

    self.Tasks = {}
    self.Order = {}
end

return Scheduler

]],
    ["src/core/tween-movement.lua"] = [[
local Players=game:GetService("Players")
local TweenService=game:GetService("TweenService")
local RunService=game:GetService("RunService")
local Workspace=game:GetService("Workspace")

local Movement={}
Movement.__index=Movement

function Movement.new(config)
    config=config or {}

    return setmetatable({
        Player=Players.LocalPlayer,
        Speed=tonumber(config.Speed) or 220,
        NearSpeed=tonumber(config.NearSpeed) or 440,
        NearDistance=math.max(tonumber(config.NearDistance) or 380,0),
        DirectDistance=math.max(tonumber(config.DirectDistance) or 12,0),
        ArrivalRadius=math.max(tonumber(config.ArrivalRadius) or 0.75,0.01),
        MinDuration=tonumber(config.MinDuration) or 0.03,
        MaxSegmentDuration=tonumber(config.MaxSegmentDuration) or 3,
        SegmentPause=tonumber(config.SegmentPause) or 0.5,
        Priorities=type(config.Priorities)=="table" and config.Priorities or {},
        UsePhysics=config.UsePhysics~=false,
        Tween=nil,
        SteppedConnection=nil,
        HeartbeatConnection=nil,
        ActiveHumanoid=nil,
        ActiveRoot=nil,
        CollisionState={},
        ControlState=nil,
        LastClearCFrame=nil,
        Moving=false,
        MoveToken=0,
        ActiveOwner=nil,
        ActivePriority=-math.huge,
        Destroyed=false
    },Movement)
end

function Movement:_character()
    local character=self.Player and self.Player.Character
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    local root=character and character:FindFirstChild("HumanoidRootPart")

    if not humanoid or humanoid.Health<=0 or not root then
        return nil
    end

    return humanoid,root
end

function Movement:_toCFrame(target)
    local kind=typeof(target)

    if kind=="CFrame" then
        return target
    elseif kind=="Vector3" then
        return CFrame.new(target)
    elseif kind=="Instance" and target:IsA("BasePart") then
        return target.CFrame
    end

    return nil
end

function Movement:_isRootClear(cframe,character)
    local params=OverlapParams.new()
    params.FilterType=Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances={character}

    local ok,parts=pcall(
        Workspace.GetPartBoundsInBox,
        Workspace,
        cframe,
        Vector3.new(1.8,2,1.8),
        params
    )

    if not ok then
        return true
    end

    for _,part in ipairs(parts) do
        if part:IsA("BasePart") and part.CanCollide then
            return false
        end
    end

    return true
end

function Movement:_noclip(character)
    for _,part in ipairs(character:GetDescendants()) do
        if part:IsA("BasePart") then
            if self.CollisionState[part]==nil then
                self.CollisionState[part]=part.CanCollide
            end
            part.CanCollide=false
        end
    end
end

function Movement:_applyTravelState(humanoid,root)
    self.CollisionState={}
    self.ControlState={
        WalkSpeed=humanoid.WalkSpeed,
        JumpPower=humanoid.JumpPower,
        JumpHeight=humanoid.JumpHeight,
        AutoRotate=humanoid.AutoRotate
    }

    humanoid.WalkSpeed=0
    humanoid.JumpPower=0
    humanoid.JumpHeight=0
    humanoid.AutoRotate=false
    self:_noclip(root.Parent)
end

function Movement:_restoreTravelState(humanoid)
    for part,canCollide in pairs(self.CollisionState) do
        if part and part.Parent then
            part.CanCollide=canCollide
        end
    end
    table.clear(self.CollisionState)

    local state=self.ControlState
    self.ControlState=nil

    if humanoid and humanoid.Parent and state then
        humanoid.WalkSpeed=state.WalkSpeed
        humanoid.JumpPower=state.JumpPower
        humanoid.JumpHeight=state.JumpHeight
        humanoid.AutoRotate=state.AutoRotate
    end

    if humanoid and humanoid.Parent and humanoid.Health>0 and self.UsePhysics and humanoid:GetState()==Enum.HumanoidStateType.Physics then
        pcall(humanoid.ChangeState,humanoid,Enum.HumanoidStateType.GettingUp)
    end
end

function Movement:_resolveSpeed(remaining,requested)
    local explicit=tonumber(requested)

    if explicit and explicit>0 then
        return explicit
    end

    if self.NearSpeed and self.NearSpeed>0 and self.NearDistance>0 and remaining<=self.NearDistance then
        return self.NearSpeed
    end

    return self.Speed
end

function Movement:GetProfile()
    return {
        Speed=self.Speed,
        NearSpeed=self.NearSpeed,
        NearDistance=self.NearDistance,
        DirectDistance=self.DirectDistance,
        ArrivalRadius=self.ArrivalRadius,
        MinDuration=self.MinDuration,
        MaxSegmentDuration=self.MaxSegmentDuration,
        SegmentPause=self.SegmentPause
    }
end

function Movement:GetOwner()
    return self.ActiveOwner,self.ActivePriority
end

function Movement:IsOwnedBy(owner)
    return self.ActiveOwner~=nil and self.ActiveOwner==tostring(owner)
end

function Movement:Stop(preservePosition,owner)
    if owner~=nil and self.ActiveOwner~=nil and self.ActiveOwner~=tostring(owner) then
        return false,"owner mismatch"
    end

    self.MoveToken+=1

    local tween=self.Tween
    local stepped=self.SteppedConnection
    local heartbeat=self.HeartbeatConnection
    local humanoid=self.ActiveHumanoid
    local root=self.ActiveRoot
    local lastClear=self.LastClearCFrame

    self.Tween=nil
    self.SteppedConnection=nil
    self.HeartbeatConnection=nil
    self.ActiveHumanoid=nil
    self.ActiveRoot=nil
    self.LastClearCFrame=nil
    self.Moving=false
    self.ActiveOwner=nil
    self.ActivePriority=-math.huge

    if tween then pcall(tween.Cancel,tween) end
    if stepped then pcall(stepped.Disconnect,stepped) end
    if heartbeat then pcall(heartbeat.Disconnect,heartbeat) end

    if root and root.Parent then
        if not preservePosition and not self:_isRootClear(root.CFrame,root.Parent) and lastClear then
            root.CFrame=lastClear
        end

        root.AssemblyLinearVelocity=Vector3.zero
        root.AssemblyAngularVelocity=Vector3.zero
    end

    self:_restoreTravelState(humanoid)
    return true
end

function Movement:CancelOwner(owner,preservePosition)
    if not self:IsOwnedBy(owner) then
        return false
    end

    return self:Stop(preservePosition~=false,owner)
end

function Movement:IsMoving()
    return self.Moving==true
end

function Movement:FlyTo(target,speed,owner,priority)
    if self.Destroyed then
        return false,"destroyed"
    end

    local goal=self:_toCFrame(target)
    if not goal then
        return false,"invalid target"
    end

    local humanoid,root=self:_character()
    if not humanoid or not root then
        return false,"character unavailable"
    end

    local requestedSpeed=tonumber(speed)
    if requestedSpeed and requestedSpeed<=0 then
        return false,"invalid speed"
    end

    if self.Speed<=0 then
        return false,"invalid speed"
    end

    local moveOwner=tostring(owner or "default")
    local configuredPriority=tonumber(self.Priorities[moveOwner]) or 0
    local movePriority=tonumber(priority) or configuredPriority

    if self.Moving and self.ActiveOwner and self.ActiveOwner~=moveOwner and movePriority<self.ActivePriority then
        return false,"busy",self.ActiveOwner
    end

    self:Stop(true)
    local token=self.MoveToken
    local distance=(root.Position-goal.Position).Magnitude

    if distance<=self.ArrivalRadius then
        root.CFrame=goal
        root.AssemblyLinearVelocity=Vector3.zero
        root.AssemblyAngularVelocity=Vector3.zero
        return true
    end

    if self.DirectDistance>0 and distance<=self.DirectDistance then
        root.CFrame=goal
        root.AssemblyLinearVelocity=Vector3.zero
        root.AssemblyAngularVelocity=Vector3.zero
        return true
    end

    self.Moving=true
    self.ActiveOwner=moveOwner
    self.ActivePriority=movePriority
    self.ActiveHumanoid=humanoid
    self.ActiveRoot=root
    self:_applyTravelState(humanoid,root)

    if self:_isRootClear(root.CFrame,root.Parent) then
        self.LastClearCFrame=root.CFrame
    end

    root.AssemblyLinearVelocity=Vector3.zero
    root.AssemblyAngularVelocity=Vector3.zero

    if self.UsePhysics then
        pcall(humanoid.ChangeState,humanoid,Enum.HumanoidStateType.Physics)
    end

    self.SteppedConnection=RunService.Stepped:Connect(function()
        if token~=self.MoveToken or not root.Parent then return end

        self:_noclip(root.Parent)
        humanoid.WalkSpeed=0
        humanoid.JumpPower=0
        humanoid.JumpHeight=0
        humanoid.AutoRotate=false
    end)

    local lastClearCheck=0

    self.HeartbeatConnection=RunService.Heartbeat:Connect(function()
        if token~=self.MoveToken then return end

        if not root.Parent or humanoid.Health<=0 then
            self:Stop(true,moveOwner)
            return
        end

        root.AssemblyLinearVelocity=Vector3.zero
        root.AssemblyAngularVelocity=Vector3.zero

        local now=os.clock()
        if now-lastClearCheck>=0.15 then
            lastClearCheck=now

            if self:_isRootClear(root.CFrame,root.Parent) then
                self.LastClearCFrame=root.CFrame
            end
        end
    end)

    local completed=true

    while token==self.MoveToken do
        local delta=goal.Position-root.Position
        local remaining=delta.Magnitude

        if remaining<=self.ArrivalRadius then
            root.CFrame=goal
            break
        end

        local moveSpeed=self:_resolveSpeed(remaining,requestedSpeed)
        local segmentDuration=math.min(remaining/moveSpeed,self.MaxSegmentDuration)
        local segmentDistance=math.min(remaining,moveSpeed*self.MaxSegmentDuration)
        local nextPosition=root.Position+delta.Unit*segmentDistance
        local segmentGoal=CFrame.new(nextPosition)*goal.Rotation

        local ok,tween=pcall(function()
            return TweenService:Create(
                root,
                TweenInfo.new(math.max(segmentDuration,self.MinDuration),Enum.EasingStyle.Linear),
                {CFrame=segmentGoal}
            )
        end)

        if not ok then
            self:Stop(true,moveOwner)
            return false,tostring(tween)
        end

        self.Tween=tween
        tween:Play()

        local playbackState=tween.Completed:Wait()

        if token~=self.MoveToken then
            return false,"cancelled"
        end

        if playbackState~=Enum.PlaybackState.Completed then
            completed=false
            break
        end

        self.Tween=nil
        root.AssemblyLinearVelocity=Vector3.zero
        root.AssemblyAngularVelocity=Vector3.zero

        if remaining>segmentDistance+0.05 and self.SegmentPause>0 then
            local holdCFrame=root.CFrame
            local pauseUntil=os.clock()+self.SegmentPause

            while token==self.MoveToken and os.clock()<pauseUntil do
                if not root.Parent or humanoid.Health<=0 then
                    break
                end

                root.CFrame=holdCFrame
                root.AssemblyLinearVelocity=Vector3.zero
                root.AssemblyAngularVelocity=Vector3.zero
                RunService.Heartbeat:Wait()
            end
        end
    end

    if token~=self.MoveToken then
        return false,"cancelled"
    end

    self:Stop(true,moveOwner)
    return completed
end

function Movement:SetSpeed(value)
    value=tonumber(value)
    if not value or value<=0 then
        return false
    end

    self.Speed=value
    return true
end

function Movement:SetNearSpeed(value,distance)
    value=tonumber(value)
    distance=tonumber(distance)

    if not value or value<=0 or not distance or distance<=0 then
        return false
    end

    self.NearSpeed=value
    self.NearDistance=distance
    return true
end

function Movement:Destroy()
    if self.Destroyed then return end
    self:Stop()
    self.Destroyed=true
end

return Movement

