    local mtLabel = Instance.new("TextLabel", UI.MobileToggle)
    mtLabel.Size = UDim2.new(1, -40, 1, 0)
    mtLabel.Position = UDim2.new(0, 36, 0, 0)
    mtLabel.BackgroundTransparency = 1
