    ["src/games/bloodstrike.lua"] = [[
local game, task, type, tostring, tonumber, pairs, ipairs, pcall, math = game, task, type, tostring, tonumber, pairs, ipairs, pcall, math
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")

local LocalPlayer = Players.LocalPlayer
local env = type(getgenv) == "function" and getgenv() or _G
local STATE_KEY = "__DEPHUB_BLOODSTRIKE"

local previous = env[STATE_KEY]
if type(previous) == "table" and type(previous.Destroy) == "function" then
    pcall(previous.Destroy, previous)
end

if not LocalPlayer then
    return false
end

-- Blood Strike backend.
--
-- The game keeps every fighter (players and bots) as a Model under
-- workspace.Characters, named after the owner, instead of relying on the usual
-- Players.Character mirror. So the ESP resolves a character by matching the
-- Model name against the player list, then falls back to the standard
-- LocalPlayer/Players surface when that container is missing (menu, loading, a
-- private server variant) so the panel still works instead of going blank.

local State = {
    Version = "0.1.0",
    Destroyed = false,
    Started = false,
    Root = nil,
    Connections = {},
    Toggles = {
        ESP = false,
        TeamCheck = true,
        ESPNames = true,
        ESPDistance = true,
        ESPHealth = false,
        Chams = true,
    },
    ToggleLabels = {
        ESP = "ESP ativado",
        TeamCheck = "Ignorar time aliado",
        ESPNames = "Mostrar nome",
        ESPDistance = "Mostrar distancia",
        ESPHealth = "Mostrar vida",
        Chams = "Chams (contorno)",
    },
    Values = {
        Range = 1000,
        ESPColor = Color3.fromRGB(255, 70, 70),
        EnemyColor = Color3.fromRGB(255, 70, 70),
        AllyColor = Color3.fromRGB(80, 200, 255),
        TextSize = 13,
    },
    ESPObjects = {},
}

env[STATE_KEY] = State
env.__DEPHUB = env.__DEPHUB or {}
env.__DEPHUB.BloodStrike = State

local function characterParts(player)
    local character = player.Character
    if not character then return nil, nil, nil end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local root = character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("Head")
    return character, humanoid, root
end

-- A character Model in workspace.Characters is named after its owner. Resolve it
-- back to the Player so team checks and the player list stay authoritative.
local function playerForModel(model)
    if not model then return nil end
    local player = Players:GetPlayerFromCharacter(model)
    if player then return player end
    local name = model.Name
    for _, candidate in ipairs(Players:GetPlayers()) do
        if candidate.Name == name or candidate.DisplayName == name then return candidate end
    end
    return nil
end

-- The ESP is driven off workspace.Characters when it exists; otherwise it falls
-- back to the players whose Character lives under the standard container. Both
-- paths yield {model, player} pairs the rest of the module treats identically.
local function eachFighter()
    local list = {}
    local container = Workspace:FindFirstChild("Characters")
    if container then
        for _, model in ipairs(container:GetChildren()) do
            if model:IsA("Model") then
                list[#list + 1] = {model = model, player = playerForModel(model)}
            end
        end
    end
    if #list == 0 then
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer and player.Character then
                list[#list + 1] = {model = player.Character, player = player}
            end
        end
    end
    return list
end

local function isAlly(player)
    if not player or not LocalPlayer then return false end
    if player == LocalPlayer then return true end
    if LocalPlayer.Team ~= nil and player.Team ~= nil then return player.Team == LocalPlayer.Team end
    if LocalPlayer.TeamColor ~= nil and player.TeamColor ~= nil then return player.TeamColor == LocalPlayer.TeamColor end
    return false
end

local function colorFor(player)
    if State.Toggles.TeamCheck and isAlly(player) then return State.Values.AllyColor end
    return State.Values.EnemyColor
end

function State:RemoveESP(model)
    local record = self.ESPObjects[model]
    if not record then return end
    self.ESPObjects[model] = nil
    for _, object in pairs(record) do
        if typeof(object) == "Instance" then pcall(object.Destroy, object) end
    end
end

function State:ClearESP()
    for model in pairs(self.ESPObjects) do
        self:RemoveESP(model)
    end
end

function State:CreateESP(model, player)
    self:RemoveESP(model)
    if self.Destroyed or not self.Toggles.ESP or not model then return end
    if self.Toggles.TeamCheck and isAlly(player) then return end
    local head = model:FindFirstChild("Head") or model:FindFirstChild("HumanoidRootPart")
    if not head then return end

    local color = colorFor(player)
    local billboard = Instance.new("BillboardGui")
    billboard.Name = "DepHubESP"
    billboard.AlwaysOnTop = true
    billboard.Size = UDim2.fromOffset(220, 46)
    billboard.StudsOffset = Vector3.new(0, 2.8, 0)
    billboard.Adornee = head
    billboard.Parent = head

    local label = Instance.new("TextLabel")
    label.BackgroundTransparency = 1
    label.Size = UDim2.fromScale(1, 1)
    label.Font = Enum.Font.GothamBold
    label.TextStrokeTransparency = 0.35
    label.TextColor3 = color
    label.TextSize = self.Values.TextSize
    label.Parent = billboard

    local highlight
    if self.Toggles.Chams then
        highlight = Instance.new("Highlight")
        highlight.Name = "DepHubChams"
        highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        highlight.FillColor = color
        highlight.FillTransparency = 0.55
        highlight.OutlineColor = Color3.new(1, 1, 1)
        highlight.Adornee = model
        highlight.Parent = model
    end

    self.ESPObjects[model] = {Billboard = billboard, Label = label, Highlight = highlight}
end

function State:SetESP(enabled)
    self.Toggles.ESP = enabled == true
    if not self.Toggles.ESP then
        self:ClearESP()
        return true
    end
    self:Refresh()
    return true
end

-- Reconcile every frame: create records for fighters in range, drop stale ones,
-- and repaint the survivors. Team check and range are re-evaluated live so a
-- toggle or slider change is visible without a relock.
function State:Refresh()
    if self.Destroyed or not self.Toggles.ESP then return end
    local _, _, localRoot = characterParts(LocalPlayer)
    local seen = {}
    for _, entry in ipairs(eachFighter()) do
        local model, player = entry.model, entry.player
        if model ~= (LocalPlayer.Character) then
            local humanoid = model:FindFirstChildOfClass("Humanoid")
            local root = model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Head")
            local distance = 0
            if localRoot and root and localRoot.Position and root.Position then
                local delta = root.Position - localRoot.Position
                distance = math.floor(delta.Magnitude or 0)
            end
            local ally = self.Toggles.TeamCheck and isAlly(player)
            local visible = not ally and distance <= self.Values.Range
            if visible then
                seen[model] = true
                local record = self.ESPObjects[model]
                if not record then
                    self:CreateESP(model, player)
                    record = self.ESPObjects[model]
                end
                if record then
                    local color = colorFor(player)
                    record.Label.TextColor3 = color
                    if record.Highlight then record.Highlight.FillColor = color end
                    local text = {}
                    if self.Toggles.ESPNames then
                        text[#text + 1] = player and (player.DisplayName or player.Name) or model.Name
                    end
                    if self.Toggles.ESPHealth and humanoid and humanoid.Health then text[#text + 1] = math.floor(humanoid.Health) .. " HP" end
                    if self.Toggles.ESPDistance then text[#text + 1] = distance .. "m" end
                    record.Label.Text = table.concat(text, " | ")
                    record.Label.TextSize = self.Values.TextSize
                    record.Billboard.Enabled = true
                    if record.Highlight then record.Highlight.Enabled = true end
                end
            end
        end
    end
    for model in pairs(self.ESPObjects) do
        if not seen[model] then self:RemoveESP(model) end
    end
end

function State:SetToggle(name, enabled)
    if self.Destroyed or type(name) ~= "string" then return false end
    if self.Toggles[name] == nil then return false end
    self.Toggles[name] = enabled == true
    if name == "ESP" then
        return self:SetESP(enabled)
    elseif name == "TeamCheck" or name == "Chams" then
        -- A team/chams change alters which records exist, so rebuild.
        if self.Toggles.ESP then self:ClearESP(); self:Refresh() end
    end
    return true
end

function State:GetToggle(name)
    if self.Destroyed or type(name) ~= "string" then return false end
    return self.Toggles[name] == true
end

function State:SetRange(value)
    value = tonumber(value)
    if not value or value ~= value or value < 1 then return false end
    self.Values.Range = math.clamp(math.floor(value), 1, 100000)
    return true
end

function State:SetTextSize(value)
    value = tonumber(value)
    if not value or value ~= value then return false end
    self.Values.TextSize = math.clamp(math.floor(value), 6, 40)
    return true
end

function State:Start()
    if self.Started or self.Destroyed then return false end
    self.Started = true
    local connection = RunService.RenderStepped:Connect(function()
        if not self.Destroyed and self.Toggles.ESP then self:Refresh() end
    end)
    self.Connections[#self.Connections + 1] = connection
    return true
end

function State:Destroy()
    if self.Destroyed then return end
    self.Destroyed = true
    self:ClearESP()
    for _, connection in ipairs(self.Connections) do
        if typeof(connection) == "Instance" or type(connection) == "table" then
            pcall(function() connection:Disconnect() end)
        end
    end
    self.Connections = {}
    if env[STATE_KEY] == self then env[STATE_KEY] = nil end
    if env.__DEPHUB and env.__DEPHUB.BloodStrike == self then env.__DEPHUB.BloodStrike = nil end
end

-- ---------------------------------------------------------------------------
-- Presentation: the shared shell. Tabs and sections are the backend's job.
-- ---------------------------------------------------------------------------
local function sectionFor(tab, name, column, summary)
    if not (tab and type(tab.CreateSection) == "function") then return nil end
    local ok, section = pcall(function() return tab:CreateSection(name, summary, column) end)
    if ok then return section end
    return nil
end

do
    local UI = env.__DEPHUB and env.__DEPHUB.UI
    if type(UI) == "table" and type(UI.CreateTab) == "function" then
        local okTab, tab = pcall(function() return UI:CreateTab("ESP", "All") end)
        if okTab and tab then
            local visual = sectionFor(tab, "Jogadores", "Left", "Contorno e informacao sobre os inimigos")
            if visual then
                visual:CreateToggle("ESP ativado", State.Toggles.ESP, function(v) State:SetToggle("ESP", v) end)
                visual:CreateToggle("Ignorar time aliado", State.Toggles.TeamCheck, function(v) State:SetToggle("TeamCheck", v) end)
                visual:CreateToggle("Chams (contorno)", State.Toggles.Chams, function(v) State:SetToggle("Chams", v) end)
            end
            local info = sectionFor(tab, "Informacao", "Right", "O que aparece em cima de cada alvo")
            if info then
                info:CreateToggle("Mostrar nome", State.Toggles.ESPNames, function(v) State.Toggles.ESPNames = v == true end)
                info:CreateToggle("Mostrar distancia", State.Toggles.ESPDistance, function(v) State.Toggles.ESPDistance = v == true end)
                info:CreateToggle("Mostrar vida", State.Toggles.ESPHealth, function(v) State.Toggles.ESPHealth = v == true end)
                info:CreateSlider("Distancia maxima", 50, 5000, State.Values.Range, function(v) State:SetRange(v) end)
                info:CreateSlider("Tamanho do texto", 8, 30, State.Values.TextSize, function(v) State:SetTextSize(v) end)
            end
        end
    end
end

State:Start()

do
    local Diag = env.__DEPHUB and env.__DEPHUB.Diagnostics
    if Diag and type(Diag.RegisterModule) == "function" then
        Diag:RegisterModule("src/games/bloodstrike.lua")
        Diag:Feature("BloodStrike.ESP", function() return State.Toggles.ESP and "ON" or "off" end)
        Diag:Feature("BloodStrike.TeamCheck", function() return State.Toggles.TeamCheck and "ON" or "off" end)
        Diag:Watch("BloodStrike alvos", function() return tostring((function()
            local n = 0
            for _ in pairs(State.ESPObjects) do n = n + 1 end
            return n
        end)()) end)
        Diag:Command("bs", function()
            local container = Workspace:FindFirstChild("Characters")
            return "esp=" .. tostring(State.Toggles.ESP) ..
                " team=" .. tostring(State.Toggles.TeamCheck) ..
                " characters=" .. tostring(container and #container:GetChildren() or 0)
        end)
    end
end

env.BS = State

return State

]],
    ["src/games/bloxfruits.lua"] = [[
local game = game
local type = type
local tostring = tostring

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local env = type(getgenv) == "function" and getgenv() or _G
local report = (env.__DEPHUB and type(env.__DEPHUB.Log) == "function") and env.__DEPHUB.Log or function() end

-- Backend for the vendored open-source Blox Fruits script.
--
-- It owns no presentation: the DepHub frontend renders from this contract and
-- the feature state lives in the adapter's control registry. Every method is a
-- thin forwarder, so there is exactly one source of truth for a toggle.

local OSS_PATH = "src/games/features/bloxfruits/oss/"
local VERSION = "1.0.0"

local previous = type(env.__DEPHUB_BLOXFRUITS_OSS) == "table" and env.__DEPHUB_BLOXFRUITS_OSS or nil
if previous and type(previous.Destroy) == "function" then pcall(previous.Destroy, previous) end

local sourceBase = (env.__DEPHUB or {}).SourceBaseURL or "https://raw.githubusercontent.com/glowpkj/DepHub/main/"

-- Prefer the bundle's resolver published on the shared environment. It is only
-- present in a bundled build; a source checkout resolves through the loader's
-- own fetch path, so fall back to the executor primitives in that order.
local function fetch(path)
    local cb = tostring((env.__DEPHUB or {}).SourceCacheBust or "")
    local url = sourceBase .. path .. (cb ~= "" and ("?cb=" .. cb) or "")
    local resolver = (type(env.__dephubHttpGet) == "function" and env.__dephubHttpGet)
        or (type(env.__DEPHUB_HTTP_GET) == "function" and env.__DEPHUB_HTTP_GET)
        or (type(_G.__dephubHttpGet) == "function" and _G.__dephubHttpGet)
        or (type(_G.__DEPHUB_HTTP_GET) == "function" and _G.__DEPHUB_HTTP_GET)
    if resolver then
        local ok, source = pcall(resolver, url)
        if ok and type(source) == "string" and #source > 0 then return true, source end
    end
    local ok, source = pcall(function() return __dephubHttpGet(url) end)
    if ok and type(source) == "string" and #source > 0 then return true, source end
    return false, tostring(source)
end

local function loadFactory(path)
    local okFetch, source = fetch(path)
    if not okFetch then return false, "fetch: " .. tostring(source) end
    local chunk, chunkError = loadstring(source)
    if not chunk then return false, "compile: " .. tostring(chunkError) end
    local okRun, factory = pcall(chunk)
    if not okRun or type(factory) ~= "table" then return false, "run: " .. tostring(factory) end
    return true, factory
end

-- The adapter's LoadSource contract is "hand me the source string", while fetch
-- reports (ok, source). Wrap so a missing module surfaces the failing path.
local function loadSource(path)
    local ok, source = fetch(path)
    if ok then return source end
    return nil, tostring(source)
end

local LocalPlayer = game:GetService("Players").LocalPlayer
if not LocalPlayer then
    report("BloxFruits: LocalPlayer ausente")
    return false
end

local okFactory, Adapter = loadFactory(OSS_PATH .. "adapter.lua")
if not okFactory then
    report("BloxFruits: adapter falhou: " .. tostring(Adapter))
    return false
end

local Context = {
    Vendors = {game = game, task = task},
    Env = env,
    Sea = "Sea1",
    Version = VERSION,
    Warn = report,
    PathPrefix = OSS_PATH,
    LoadSource = loadSource
}

local okNew, State, reason = pcall(Adapter.new, Context)
if not okNew or type(State) ~= "table" then
    report("BloxFruits: OSS nao inicializou: " .. tostring(State) .. (reason and (" | " .. tostring(reason)) or ""))
    return false
end

env.__DEPHUB_BLOXFRUITS_OSS = State
env.__DEPHUB = env.__DEPHUB or {}
env.__DEPHUB.BloxFruits = State
env.__DEPHUB.BloxFruitsOSS = State

-- Public toggles: one per control the modules registered, so a frontend can
-- mirror them with the generic SetToggle/GetToggle path it already uses.
State.Toggles = {}
State.ToggleLabels = {}
for _, definition in ipairs(State:ListControls()) do
    if definition.kind == "toggle" then
        State.Toggles[definition.key] = definition.get() == true
        State.ToggleLabels[definition.key] = definition.page .. " / " .. definition.title
    end
end

function State:SetToggle(name, enabled)
    if self.Destroyed or type(name) ~= "string" then return false end
    local control = self:GetControl(name)
    if not control or control.kind ~= "toggle" then return false end
    if not self:SetControl(name, enabled == true) then return false end
    self.Toggles[name] = control.get() == true
    return true
end

function State:GetToggle(name)
    if self.Destroyed then return false end
    local control = self:GetControl(name)
    if not control then return self.Toggles[name] == true end
    return control.get() == true
end

function State:GetValue(name, fallback)
    local value = self:GetControlValue(name)
    if value == nil then return fallback end
    return value
end

function State:SetValue(name, value)
    local ok = self:SetControl(name, value)
    local control = self:GetControl(name)
    if ok and control and control.kind == "toggle" then self.Toggles[name] = control.get() == true end
    return ok
end

-- Core.spawn hands every loop back so the frontend's Rejoin can restart the
-- work the game cancelled on teleport (resume.lua used to call this).
local CoreThreads = (State.Core and State.Core._threads) or {}

local function resumeAll()
    local resumed = 0
    for _, thread in ipairs(CoreThreads) do
        if type(thread) == "thread" and coroutine.status(thread) == "suspended" then
            local ok = pcall(task.spawn, thread)
            if ok then resumed += 1 end
        end
    end
    return resumed
end

State.ResumeAll = resumeAll

function State:Rejoin()
    self:ResumeAll()
    return true
end

function State:ServerHop()
    local ok, module = pcall(function() return self.Modules and self.Modules.events end)
    if ok and type(module) == "table" and type(module.serverHop) == "function" then
        pcall(module.serverHop, module)
        return true
    end
    return false
end

function State:Destroy()
    if self.Destroyed then return end
    pcall(function() self:Unload() end)
    self.Destroyed = true
    if env.__DEPHUB_BLOXFRUITS_OSS == self then env.__DEPHUB_BLOXFRUITS_OSS = nil end
    if env.__DEPHUB and env.__DEPHUB.BloxFruits == self then env.__DEPHUB.BloxFruits = nil end
    if env.__DEPHUB and env.__DEPHUB.BloxFruitsOSS == self then env.__DEPHUB.BloxFruitsOSS = nil end
end


local visual = env.__DEPHUB and env.__DEPHUB.UI
local uiModel = State.UI
local pageAliases = {
    ["Info"] = "Home",
    ["Farm"] = "Farm",
    ["Farm 2"] = "Farm",
    ["Farm 3"] = "Farm",
    ["PVP"] = "Combat",
    ["Teleport"] = "Teleport",
    ["Sea"] = "Travel",
    ["Fruit"] = "Fruits",
    ["Shop"] = "Shop",
    ["Shop 2"] = "Shop",
    ["Shop 3"] = "Shop",
    ["Raids/Events"] = "Events",
    ["Extras"] = "Extras",
    ["Player"] = "Player",
    ["Config"] = "Settings"
}
local tabOrder = {"Info", "Farm", "Farm 2", "Farm 3", "PVP", "Teleport", "Sea", "Fruit", "Shop", "Shop 2", "Shop 3", "Raids/Events", "Extras", "Player", "Config"}
local renderedTabs = {}
local renderedSections = {}
local function splitSeas(value)
    local result = {}
    for sea in string.gmatch(tostring(value or ""), "[^,]+") do
        result[string.gsub(sea, "%s+", "")] = true
    end
    return result
end
local function categoryForControl(sea)
    local value = tostring(sea or "All")
    if value == "All" or value == "" then return "General" end
    local seas = splitSeas(value)
    if seas.Sea1 and seas.Sea2 and seas.Sea3 then return "General" end
    -- A control scoped to more than one sea belongs to whichever of those seas the
    -- player is on right now: on Sea 2, "Sea2,Sea3" is a Sea 2 feature. The header
    -- therefore only ever shows the current sea's category, never a combined one,
    -- so a shared feature never drags another sea's category into view.
    local current = tostring(State.Sea or "Sea1")
    if seas[current] then
        if current == "Sea1" then return "Sea 1" end
        if current == "Sea2" then return "Sea 2" end
        if current == "Sea3" then return "Sea 3" end
    end
    if seas.Sea1 and seas.Sea2 then return "Sea 1/2" end
    if seas.Sea2 and seas.Sea3 then return "Sea 2/3" end
    if seas.Sea1 then return "Sea 1" end
    if seas.Sea2 then return "Sea 2" end
    if seas.Sea3 then return "Sea 3" end
    return "General"
end
-- Tabs that must stay reachable no matter which sea the player is on. Teleport
-- is the way to travel between seas (it holds the Sea 1/2/3 waypoints), and the
-- Info/PVP/Player/Config pages are game-wide rather than belonging to a sea.
local ALWAYS_VISIBLE = {
    Home = true, Combat = true, Teleport = true, Player = true, Settings = true
}

local function ensureTab(name, sea)
    local category = categoryForControl(sea)
    -- A logical tab can be shared by more than one sea (Farm, Shop). The sea
    -- scope stored on the shell tab is what decides whether it is shown, so a
    -- tab that carries a sea keeps it; the always-visible pages drop their scope.
    local scope = ALWAYS_VISIBLE[name] and nil or sea
    local key = category .. "|" .. name
    if renderedTabs[key] ~= nil then return renderedTabs[key] or nil end
    -- The Blox Fruits backend owns its sea categories: the shared shell only
    -- creates "General", so this backend registers the seas it uses. Each sea
    -- category gets its own icon so the header reads as designed rather than a
    -- row of identical "layers" glyphs.
    local CATEGORY_ICONS = {["General"] = "layers", ["Sea 1"] = "waves", ["Sea 2"] = "sailboat", ["Sea 3"] = "skull", ["Sea 1/2"] = "waves", ["Sea 2/3"] = "waves"}
    if type(visual.CreateCategory) == "function" then visual:CreateCategory(category, CATEGORY_ICONS[category]) end
    local tab = visual:CreateTab(name, category, scope)
    if not tab then
        -- Remember the failure so the next control in this group does not try
        -- again: without this the same tab is retried for every control.
        renderedTabs[key] = false
        report("BloxFruits: não foi possível criar a aba " .. name .. " (" .. category .. ")")
        return nil
    end
    local record = {Tab = tab, Sea = scope, Name = name, Category = category, Key = key, Columns = {Left = 0, Right = 0}}
    renderedTabs[key] = record
    return record
end
local function groupFor(definition)
    local key = tostring(definition.key or ""):lower()
    local title = tostring(definition.title or ""):lower()
    local value = key .. " " .. title
    if value:find("config") or value:find("save") or value:find("load") then return "Configuration" end
    if value:find("quest") or value:find("level") or value:find("farm") or value:find("mastery") or value:find("stat") or value:find("bring") or value:find("collect") then return "Farming" end
    if value:find("fruit") or value:find("dealer") or value:find("spin") or value:find("storage") then return "Fruits" end
    if value:find("raid") or value:find("event") or value:find("leviathan") or value:find("mirage") or value:find("sea beast") or value:find("bones") then return "Events" end
    if value:find("island") or value:find("teleport") or value:find("waypoint") or value:find("travel") or value:find("sea travel") or value:find("boss") then return "Travel" end
    if value:find("player") or value:find("walk") or value:find("speed") or value:find("jump") or value:find("esp") or value:find("afk") or value:find("ken") or value:find("buso") then return "Player" end
    if value:find("shop") or value:find("buy") or value:find("weapon") or value:find("style") or value:find("accessory") or value:find("race") then return "Shop & Upgrades" end
    if value:find("aim") or value:find("attack") or value:find("combat") or value:find("aura") or value:find("bounty") or value:find("pvp") or value:find("skill") or value:find("stun") or value:find("target") or value:find("sword") or value:find("gun") then return "Combat" end
    if value:find("info") or value:find("status") or value:find("version") then return "Overview" end
    return "Other"
end
local function sectionFor(tabRecord, group)
    if not tabRecord or not tabRecord.Tab then return nil end
    local key = tabRecord.Key .. "|" .. group
    if renderedSections[key] then return renderedSections[key] end
    local column = tabRecord.Columns.Left <= tabRecord.Columns.Right and "Left" or "Right"
    tabRecord.Columns[column] += 1
    local section = tabRecord.Tab:CreateSection(group, column)
    renderedSections[key] = section
    return section
end
local function renderDefinition(definition, section)
    local title = tostring(definition.title or definition.key or "Control")
    -- Show the control's own description as a caption when the modules provided
    -- one that adds information beyond the title. This is the §11 "descrições"
    -- pass: the text already flowed into the control registry, it was just never
    -- rendered.
    local description = tostring(definition.description or "")
    if description ~= "" and description:lower() ~= title:lower() and section.CreateParagraph then
        section:CreateParagraph(title, description)
    end
    local function set(value) State:SetControl(definition.key, value) end
    if definition.kind == "toggle" then
        section:CreateToggle(title, definition.get and definition.get() == true, set)
    elseif definition.kind == "slider" then
        section:CreateSlider(title, definition.min, definition.max, definition.get and definition.get() or definition.default, set)
    elseif definition.kind == "dropdown" then
        section:CreateDropdown(title, definition.options or {}, definition.get and definition.get() or definition.default, set)
    elseif definition.kind == "button" then
        section:CreateButton(title, function() set(true) end)
    elseif definition.kind == "textbox" then
        section:CreateInput(title, title, definition.get and definition.get() or "", set)
    end
end
if type(visual) == "table" and type(visual.CreateTab) == "function" then
    for _, pageName in ipairs(tabOrder) do
        local page = uiModel.tabs[pageName]
        if page then
            local logicalName = pageAliases[pageName] or pageName
            if #page.controls == 0 then
                local record = ensureTab(logicalName, page.sea)
                if pageName == "Info" then
                    local section = sectionFor(record, "Overview")
                    if section then section:CreateParagraph("DepHub", "Controles organizados por categoria. Apenas Anti-AFK fica ligado por padrão.") end
                    -- Feature search: filters the tab buttons by name so a feature
                    -- can be found without knowing which sea holds it. Clearing the
                    -- box shows everything again.
                    local searchSection = sectionFor(record, "Find")
                    if searchSection then
                        searchSection:CreateInput("Search features", "Type to filter tabs...", "", function(value)
                            if type(visual.Search) == "function" then visual:Search(tostring(value or "")) end
                        end)
                        searchSection:CreateButton("Clear search", function()
                            if type(visual.Search) == "function" then visual:Search("") end
                        end)
                    end
                    -- Automation status: a live read of which toggles are on. The
                    -- paragraph is a snapshot taken at load; the button reports the
                    -- current state so the player can confirm at any time.
                    local statusSection = sectionFor(record, "Status")
                    if statusSection then
                        local function activeList()
                            local parts = {}
                            for key, value in pairs(State.Toggles or {}) do
                                if value then parts[#parts + 1] = tostring(key) end
                            end
                            table.sort(parts)
                            return parts
                        end
                        local snapshot = activeList()
                        statusSection:CreateParagraph("Automations ON",
                            #snapshot > 0 and table.concat(snapshot, ", ") or "Nenhuma automação ligada.")
                        statusSection:CreateButton("Refresh status", function()
                            local parts = activeList()
                            visual:Notify("Status", #parts > 0 and table.concat(parts, ", ") or "Nenhuma automação ligada.", 6)
                        end)
                    end
                    local seaSection = sectionFor(record, "Sea")
                    if seaSection then
                        -- Single sea selector. The game reports the current sea
                        -- automatically (info.lua polls Realm) and this lets the
                        -- player override it; both paths end in applySea, which
                        -- filters the tabs down to the chosen sea.
                        local seaLabels = {Sea1 = "Sea 1", Sea2 = "Sea 2", Sea3 = "Sea 3"}
                        local seaValues = {["Sea 1"] = "Sea1", ["Sea 2"] = "Sea2", ["Sea 3"] = "Sea3"}
                        local currentLabel = seaLabels[State.Sea] or "Sea 1"
                        seaSection:CreateDropdown("Sea", {"Sea 1", "Sea 2", "Sea 3"}, currentLabel, function(value)
                            State:SetSea(seaValues[tostring(value)] or "Sea1")
                            visual:Notify("Sea", "Conteúdo filtrado para " .. tostring(value))
                        end)
                    end
                elseif pageName == "Config" then
                    local section = sectionFor(record, "Configuration")
                    if section then
                        local configName = "default"
                        local renameTo = ""
                        section:CreateInput("Nome da configuração", "Nome da configuração", configName, function(value) configName = tostring(value or "default") end)
                        section:CreateButton("Salvar configuração", function()
                            local name = tostring(configName ~= "" and configName or "default")
                            if State:SaveConfig(name) then visual:Notify("Config", "Configuração salva: " .. name) else visual:Notify("Config", "Não foi possível salvar.") end
                        end)
                        section:CreateButton("Carregar configuração", function()
                            local name = tostring(configName ~= "" and configName or "default")
                            if State:LoadConfig(name) then visual:Notify("Config", "Configuração carregada: " .. name) else visual:Notify("Config", "Não foi possível carregar.") end
                        end)
                        section:CreateButton("Excluir configuração", function()
                            local name = tostring(configName ~= "" and configName or "default")
                            if State:DeleteConfig(name) then visual:Notify("Config", "Configuração excluída: " .. name) else visual:Notify("Config", "Não foi possível excluir (inexistente?).") end
                        end)
                        section:CreateButton("Listar configurações", function()
                            local names = State:ListConfigs()
                            if #names == 0 then visual:Notify("Config", "Nenhuma configuração salva.") else visual:Notify("Config", table.concat(names, ", "), 6) end
                        end)
                        -- Rename reads the "Nome" box as the source and a second box
                        -- as the target, so no extra state is needed beyond the two.
                        section:CreateInput("Renomear para", "Novo nome", renameTo, function(value) renameTo = tostring(value or "") end)
                        section:CreateButton("Renomear configuração", function()
                            local from = tostring(configName ~= "" and configName or "default")
                            local to = tostring(renameTo ~= "" and renameTo or "")
                            if to == "" then visual:Notify("Config", "Informe o novo nome no campo acima.") return end
                            if State:RenameConfig(from, to) then visual:Notify("Config", "Renomeada: " .. from .. " -> " .. to) else visual:Notify("Config", "Não foi possível renomear (origem inexistente ou destino já existe).") end
                        end)
                    end
                    local reset = sectionFor(record, "Reset")
                    if reset then
                        reset:CreateButton("Restaurar padrões (tudo)", function()
                            State:ResetDefaults()
                            visual:Notify("Config", "Todos os controles voltaram ao padrão.")
                        end)
                        -- Reset a single module without touching the others. The
                        -- page names map to modules in the core module registry.
                        local modules = {"combat", "farm", "player", "fruits", "shop", "events", "extras", "teleport"}
                        local chosen = "combat"
                        reset:CreateDropdown("Módulo", modules, chosen, function(value) chosen = tostring(value or "combat") end)
                        reset:CreateButton("Restaurar módulo", function()
                            local n = State:ResetModule(chosen)
                            if n > 0 then visual:Notify("Config", "Módulo " .. chosen .. " restaurado (" .. n .. " controles).") else visual:Notify("Config", "Nenhum controle restaurável em " .. chosen .. ".") end
                        end)
                    end
                end
            else
                for _, definition in ipairs(page.controls) do
                    local sea = definition.sea or page.sea
                    local record = ensureTab(logicalName, sea)
                    local section = sectionFor(record, groupFor(definition))
                    if section then renderDefinition(definition, section) end
                end
            end
        end
    end
    local function applySea(sea)
        if type(visual.SetCurrentSea) == "function" then visual:SetCurrentSea(sea or "Sea1") end
    end
    if type(uiModel.onSea) == "function" then uiModel.onSea(applySea) else applySea(State.Sea or "Sea1") end
    State.UIFrontend = visual
    State.UITabs = renderedTabs
end

-- Report the Blox Fruits backend into the shared Debug tab. Modules are
-- reported by load outcome, then the control registry is exposed as live
-- features so the player can see exactly which toggles are on and why a module
-- failed to load.
do
    local Diag = env.__DEPHUB and env.__DEPHUB.Diagnostics
    if Diag and type(Diag.RegisterModule) == "function" then
        Diag:SetEnvironment({["BloxFruits sea"] = tostring(State.Sea or "?")})
        local modules = State.Modules or {}
        for _, name in ipairs({"core", "teleport", "combat", "farm", "player", "fruits", "shop", "events", "extras", "info"}) do
            Diag:RegisterModule("features/bloxfruits/oss/" .. name .. ".lua")
            local loaded = type(modules[name]) == "table"
            local detail = loaded and "carregado" or "ausente"
            if not loaded and type(State.Errors) == "table" and State.Errors[name] ~= nil then detail = tostring(State.Errors[name]) end
            Diag:Module("features/bloxfruits/oss/" .. name .. ".lua", loaded, detail)
        end
        local toggleCount, onCount = 0, 0
        for key, value in pairs(State.Toggles or {}) do
            toggleCount = toggleCount + 1
            if value then onCount = onCount + 1 end
        end
        Diag:Note("BloxFruits toggles: " .. tostring(onCount) .. " ligados de " .. tostring(toggleCount))
        Diag:Feature("BloxFruits.Sea", function() return tostring(State.Sea or "?") end)
        Diag:Feature("BloxFruits.Toggles ligados", function()
            local parts = {}
            for key, value in pairs(State.Toggles or {}) do
                if value then parts[#parts + 1] = key end
            end
            table.sort(parts)
            return #parts > 0 and table.concat(parts, ", ") or "nenhum"
        end)
        Diag:Feature("BloxFruits.LastError", function() return tostring(State.LastError or "none") end)
        if type(Diag.Watch) == "function" then
            Diag:Watch("BloxFruits sea", function() return tostring(State.Sea or "?") end)
            Diag:Watch("BloxFruits modulos", function()
                local loaded = 0
                for _, module in pairs(State.Modules or {}) do if type(module) == "table" then loaded = loaded + 1 end end
                return loaded
            end)
        end
        if type(Diag.Command) == "function" then
            Diag:Command("bf", function()
                return "sea=" .. tostring(State.Sea or "?") .. " modulos=" .. tostring((function()
                    local n = 0
                    for _, module in pairs(State.Modules or {}) do if type(module) == "table" then n = n + 1 end end
                    return n
                end)())
            end)
        end
    end
end

return State

]],
    ["src/games/features/aotr/assistance.lua"] = [[
-- Optional helpers adapted from aotr_corrigido_v3. Paths remain runtime assumptions.
local Feature = {}
function Feature.new(context)
    local self = {Jobs = {}, States = {}, Injuries = {}, Destroyed = false}
    local player = context.Player
    local function path(root, ...)
        for _, name in ipairs({...}) do root = root and root:FindFirstChild(name) end
        return root
    end
    local function report(name, message)
        self.States[name] = tostring(message)
        context.Warn(name .. ": " .. tostring(message))
    end
    local function stop(name)
        local job = self.Jobs[name]
        self.Jobs[name] = nil
        if job then
            job.Active = false
            if job.Connection then job.Connection:Disconnect() end
            if job.Thread then pcall(task.cancel, job.Thread) end
        end
    end
    local function restoreInjuries()
        for injury, entry in pairs(self.Injuries) do
            -- Do not put injuries from a previous character into the new character.
            if entry.Character == player.Character and entry.Parent.Parent then
                local ok, err = pcall(function() injury.Parent = entry.Parent end)
                if not ok then report("AntiInjury", err) end
            else pcall(function() injury:Destroy() end) end
        end
        self.Injuries = {}
    end
    local function invoke(...)
        local remote = path(game:GetService("ReplicatedStorage"), "Assets", "Remotes", "GET")
        if not remote or not remote:IsA("RemoteFunction") then error("Assets.Remotes.GET unavailable") end
        return remote:InvokeServer(...)
    end
    local function top()
        return path(player, "PlayerGui", "Interface", "HUD", "Main", "Top")
    end
    local function visible(gui)
        if not gui or not gui:IsA("GuiObject") then return false end
        local item = gui
        while item and item ~= player do
            if item:IsA("GuiObject") and not item.Visible then return false end
            if item:IsA("ScreenGui") and not item.Enabled then return false end
            item = item.Parent
        end
        return true
    end
    local ticks = {}
    function ticks.AutoBladeRefill(job)
        local character = player.Character
        local blade = path(character, "Rig_" .. player.Name, "LeftHand", "Blade_1")
        if not blade or not blade:IsA("BasePart") then return "waiting: Rig/LeftHand/Blade_1" end
        if blade.Transparency ~= 1 then job.Reloading = nil; return "blade equipped" end
        if character:GetAttribute("IFrames") ~= nil then return "waiting: IFrames" end
        local hud = top()
        local sets = path(hud and hud:FindFirstChild("Blade", true), "Sets")
        if not sets or not (sets:IsA("TextLabel") or sets:IsA("TextButton")) then return "waiting: Blade.Sets" end
        local available = tonumber(sets.Text:match("(%d+)%s*/"))
        if not available or available <= 0 then return "no blade sets / unreadable HUD" end
        if job.Character ~= character then job.Character = character; job.Reloading = nil end
        job.Reloading = job.Reloading or os.clock()
        if os.clock() - job.Reloading >= 30 then return "reload timeout; toggle off/on to retry" end
        invoke("Blades", "Reload")
        return "reload requested (unverified)"
    end
    function ticks.AntiInjury()
        local folder = path(player.Character, "Injuries")
        if not folder then return "waiting: Character.Injuries" end
        for _, injury in ipairs(folder:GetChildren()) do
            self.Injuries[injury] = {Parent = folder, Character = player.Character}
            injury.Parent = nil -- retained for restoration; never destroy current injuries
        end
        for injury, entry in pairs(self.Injuries) do
            if entry.Character ~= player.Character then
                pcall(function() injury:Destroy() end)
                self.Injuries[injury] = nil
            end
        end
        return "client injuries detached; server effect unverified"
    end
    function ticks.AutoGrabEscape(job)
        local buttons = path(player, "PlayerGui", "Interface", "Buttons")
        if not buttons then return "waiting: Interface.Buttons" end
        if job.Folder ~= buttons then
            if job.Connection then job.Connection:Disconnect() end
            job.Folder = buttons
            job.Connection = buttons.ChildAdded:Connect(function()
                if not job.Active or self.Destroyed then return end
                local ok, err = pcall(function()
                    local remote = path(game:GetService("ReplicatedStorage"), "Assets", "Remotes", "POST")
                    if not remote or not remote:IsA("RemoteEvent") then error("Assets.Remotes.POST unavailable") end
                    remote:FireServer("Attacks", "Slash_Escape")
                end)
                if not ok then report("AutoGrabEscape", err) end
            end)
        end
        return "listening: Buttons.ChildAdded (legacy trigger)"
    end
    function ticks.AutoRetry(job)
        local title = path(player, "PlayerGui", "Interface", "Rewards", "Main", "Info", "Main", "Buttons", "Retry", "Title")
        if not visible(title) or not (title:IsA("TextLabel") or title:IsA("TextButton")) then job.Requested = nil; return "waiting: visible Retry.Title" end
        if title.Text:find("STARTING", 1, true) or title.Text:find("(0/0)", 1, true) then job.Requested=nil; return "waiting: retry state" end
        if job.Requested == title then return "retry requested; waiting for next rewards screen" end
        invoke("Functions", "Retry", "Add")
        job.Requested = title
        return "retry requested (unverified)"
    end
    function self:SetToggle(name, enabled)
        if self.Destroyed then return false end
        if not ticks[name] and name ~= "AntiAFK" then return false end
        stop(name)
        if name == "AntiInjury" and not enabled then restoreInjuries() end
        self.States[name] = enabled and "starting" or "off"
        if not enabled then return true end
        local job = {Active = true}
        self.Jobs[name] = job
        if name == "AntiAFK" then
            job.Connection = player.Idled:Connect(function()
                if not job.Active or self.Destroyed then return end
                local ok, err = pcall(function()
                    local virtualUser = game:GetService("VirtualUser")
                    virtualUser:CaptureController()
                    virtualUser:ClickButton2(Vector2.new())
                end)
                if not ok then report(name, err) end
            end)
            self.States[name] = "listening: Idled"
        else
            job.Thread = task.spawn(function()
                while job.Active and not self.Destroyed do
                    local ok, status = pcall(ticks[name], job)
                    if not job.Active or self.Destroyed then return end
                    if ok then self.States[name] = status else report(name, status) end
                    task.wait(name == "AutoBladeRefill" and 1 or 0.5)
                end
            end)
        end
        return true
    end
    function self:Destroy()
        if self.Destroyed then return end
        self.Destroyed = true
        for name in pairs(self.Jobs) do stop(name) end
        restoreInjuries()
    end
    return self
end
return Feature

]],
    ["src/games/features/aotr/combat.lua"] = [[
-- Legacy remote contracts are unverified. States describe local work, never kills.
--
-- The three combat features drive the game's own remotes (Blades / Hitboxes /
-- S_Skills / Attacks / Functions). Every state string says "server unconfirmed"
-- on purpose: the client can only observe that a request was sent, so no state
-- here claims a kill or a reload actually happened server-side.
local Module={}
function Module.new(ctx)
    local path=ctx.Targets.Path
    local self={Jobs={},States={},Enabled={},Destroyed=false,CheckBusy=false,CheckResult="Disabled: not requested"}
    local effects,tracks={},{}
    local priorCharacterEffects={}
    local mover=ctx.Movement.new(ctx)
    self.Movement=mover
    function self:SetMovementSpeed(value) return mover:SetSpeed(value) end
    function self:SetNoclip(value) return mover:SetNoclip(value) end
    function self:PauseMovement() mover:Stop() end
    local ripperCharacter=nil
    local function state(name,value) self.States[name]=value end
    local function invoke(...)
        local remote=path(ctx.ReplicatedStorage,"Assets","Remotes","GET")
        if not remote or not remote:IsA("RemoteFunction") then error("Assets.Remotes.GET unavailable") end
        return remote:InvokeServer(...)
    end
    local function post(...)
        local remote=path(ctx.ReplicatedStorage,"Assets","Remotes","POST")
        if not remote or not remote:IsA("RemoteEvent") then error("Assets.Remotes.POST unavailable") end
        remote:FireServer(...)
    end
    local function restoreTracks()
        for track,speed in pairs(tracks) do pcall(function() track:AdjustSpeed(speed) end) end
        tracks={}
    end
    local function clearRipper()
        ctx.Properties:Clear("Ripper");restoreTracks();effects={}
    end
    local function stop(name)
        local job=self.Jobs[name];self.Jobs[name]=nil
        if job then job.Active=false;if job.Thread then pcall(task.cancel,job.Thread) end end
        if name=="Ripper" then clearRipper() end
        if name=="ClassicAutofarm" then mover:Stop() end
    end
    local function worker(name,tick,interval)
        if self.Jobs[name] then return end
        local job={Active=true,Character=ctx.Player.Character}
        self.Jobs[name]=job
        job.Thread=task.spawn(function()
            while job.Active and not self.Destroyed do
                local ok,result=pcall(tick,job)
                if not job.Active or self.Destroyed then return end
                if ok then state(name,result or "Running")
                else
                    state(name,"Error: "..tostring(result));ctx.Warn(name..": "..tostring(result))
                    if name=="Ripper" then clearRipper() end
                    if name=="ClassicAutofarm" then mover:Stop() end
                end
                task.wait(interval)
            end
        end)
    end
    local function ripperTick()
        local character=ctx.Player.Character
        if character~=ripperCharacter then clearRipper();ripperCharacter=character end
        if not ctx.Targets.Alive(character) then clearRipper();return "Waiting: alive character" end
        local now=ctx.Now()
        local selected=nil
        for _,part in ipairs(ctx.Workspace:GetChildren()) do
            if not priorCharacterEffects[part] and part:IsA("BasePart") and (part.Name==ctx.Player.Name.."_Steel" or part.Name==ctx.Player.Name.."_Thrust" or part.Name==ctx.Player.Name.."_RIP") then
                if not effects[part] then effects[part]=now+2 end
                if effects[part]>now and not selected then selected=part end
            end
        end
        for part in pairs(effects) do if not part.Parent then effects[part]=nil end end
        for part in pairs(priorCharacterEffects) do if not part.Parent then priorCharacterEffects[part]=nil end end
        if not selected then ctx.Properties:Clear("Ripper");restoreTracks();return "Waiting: own Steel / Thrust / RIP effect" end
        local desired={[selected]={Size=Vector3.new(125,125,125)}}
        local restorers={}
        local folder=path(ctx.Workspace,"Titans")
        local count=0
        for _,model in ipairs(folder and folder:GetChildren() or {}) do
            if model:IsA("Model") and model.Name~="Attack_Titan" then
                local nape=path(model,"Hitboxes","Hit","Nape")
                local head=path(model,"Fake","Head")
                if nape and nape:IsA("BasePart") and head and head:IsA("BasePart") then
                    -- Capture a head-relative transform once, not a guessed world position.
                    local original=ctx.Properties:Original(nape,"CFrame")
                    local offset=head.CFrame:ToObjectSpace(original)
                    restorers[nape]={CFrame=function() if head.Parent then return head.CFrame*offset end end}
                    desired[nape]={CFrame=selected.CFrame,Size=Vector3.new(150,150,150),Transparency=1}
                    count=count+1
                end
            end
        end
        ctx.Properties:Set("Ripper",desired,30,restorers)
        local humanoid=character:FindFirstChildOfClass("Humanoid")
        local animator=humanoid and humanoid:FindFirstChildOfClass("Animator")
        if animator then
            for _,track in ipairs(animator:GetPlayingAnimationTracks()) do
                if tracks[track]==nil then tracks[track]=track.Speed end
                track:AdjustSpeed(0)
            end
        end
        return "Running: local effect, "..count.." napes (server unconfirmed)"
    end
    local function updateRipper()
        if self.Enabled.TitanRipper or self.Enabled.SkillAutofarm then worker("Ripper",ripperTick,0.1)
        else stop("Ripper");state("Ripper","Disabled") end
    end
    -- Names, icon IDs and delays originate in the supplied script; unknown slots are skipped.
    -- Icon-to-ID associations follow the three legacy skill names/sequence;
    -- unlike explicit SkillId attributes, these associations still need live validation.
    local sequence={{"108","15216496277",0.1},{"14","15215073606",2.5},{"23","15215081865",0.1},{"14","15215073606",0.5}}
    local function hotbar()
        return path(ctx.Player,"PlayerGui","Interface","HUD","Main","Top","7","Hotbar")
    end
    local function equipped(id,icon)
        local bar=hotbar()
        for _,slot in ipairs(bar and bar:GetChildren() or {}) do
            if slot.Name:find("Skill",1,true) then
                local image=path(slot,"Inner","Icon")
                local matches=slot:GetAttribute("SkillId")==id or tostring(slot:GetAttribute("SkillId") or "")==id
                if icon and image and (image:IsA("ImageLabel") or image:IsA("ImageButton")) then matches=matches or image.Image:match("(%d+)$")==icon end
                if matches then
                    local cooldown=path(slot,"Cooldown")
                    if not cooldown or not cooldown:IsA("GuiObject") then return false,"missing Cooldown" end
                    return not cooldown.Visible,cooldown.Visible and "cooldown" or "ready"
                end
            end
        end
        return false,"equipment not identified"
    end
    local function skillTick(job)
        if job.Character~=ctx.Player.Character then job.Character=ctx.Player.Character;job.Step=1;job.NextAt=0 end
        local root=ctx.Targets.Alive(job.Character)
        if not root then return "Waiting: alive character" end
        if root.Anchored or job.Character:GetAttribute("IFrames")==true then return "Waiting: character unavailable / IFrames" end
        if not ctx.Targets.Select(ctx.Workspace,root) then return "Waiting: live target" end
        if ctx.Now()<(job.NextAt or 0) then return "Waiting: sequence delay" end
        local index=job.Step or 1
        local step=sequence[index]
        local ready,reason=equipped(step[1],step[2])
        job.Step=index%#sequence+1
        job.NextAt=ctx.Now()+step[3]
        if not ready then return "Waiting: skill "..step[1].." / "..reason end
        state("SkillAutofarm","Running: requesting skill "..step[1].." (server unconfirmed)")
        invoke("S_Skills","Usage",step[1])
        return "Running: skill "..step[1].." requested (server unconfirmed)"
    end
    local function classicTick(job)
        if job.Character~=ctx.Player.Character then mover:Stop();job.Character=ctx.Player.Character;job.NextAttack=0;job.Target=nil end
        local root=ctx.Targets.Alive(job.Character)
        if not root then mover:Stop();return "Waiting: alive character" end
        if root.Anchored or job.Character:GetAttribute("IFrames")==true then mover:Stop();return "Waiting: character unavailable / IFrames" end
        if ctx.IsTeleporting() then mover:Stop();return "Waiting: refill teleport" end
        local blade=path(job.Character,"Rig_"..ctx.Player.Name,"LeftHand","Blade_1")
        if not blade or not blade:IsA("BasePart") then mover:Stop();return "Waiting: blade reference" end
        if blade.Transparency==1 then
            local top=path(ctx.Player,"PlayerGui","Interface","HUD","Main","Top")
            local sets=path(top and top:FindFirstChild("Blade",true),"Sets")
            local available=sets and (sets:IsA("TextLabel") or sets:IsA("TextButton")) and tonumber(sets.Text:match("(%d+)%s*/"))
            if available~=0 then mover:Stop();return "Waiting: blade reload / enable Blade Refill" end
            local refill=ctx.FindRefill()
            if not refill then mover:Stop();return "Waiting: GasTanks.Refill" end
            mover:Move(root,refill,3)
            if (root.Position-refill.Position).Magnitude>20 then return "Running: approaching refill" end
            if ctx.Now()<(job.NextRefill or 0) then return "Waiting: refill response / HUD confirmation" end
            job.NextRefill=ctx.Now()+5
            state("ClassicAutofarm","Running: requesting full reload (server unconfirmed)")
            invoke("Blades","Full_Reload","Left",refill)
            if not job.Active or self.Destroyed or job.Character~=ctx.Player.Character then return "Waiting: character changed" end
            invoke("Blades","Full_Reload","Right",refill)
            return "Waiting: full reload requested / HUD confirmation"
        end
        local target=job.Target
        local folder=path(ctx.Workspace,"Titans")
        local humanoid=target and target.Model:FindFirstChildOfClass("Humanoid")
        if target and (not target.Part.Parent or target.Model.Parent~=folder or not humanoid or humanoid.Health<=0
            or (target.Boss and ctx.Targets.Marker(target.Model)~=target.Part)) then target=nil end
        local distance
        if not target then target,distance=ctx.Targets.Select(ctx.Workspace,root) end
        job.Target=target
        if not target then mover:Stop();return distance end
        mover:Move(root,target.Part,target.Boss and 195 or 75,target.Model)
        -- Recheck the live target/root immediately before sending an attack.
        if not target.Part.Parent or not target.Model.Parent then mover:Stop();return "Waiting: target removed" end
        distance=(root.Position-target.Part.Position).Magnitude
        if ctx.Now()<(job.NextAttack or 0) then return "Running: moving toward "..target.Model.Name end
        if distance>(target.Boss and 250 or 175) then return "Running: approaching target" end
        job.NextAttack=ctx.Now()+1
        post("Attacks","Slash",true)
        if not job.Active or self.Destroyed or job.Character~=ctx.Player.Character then return "Waiting: character changed" end
        state("ClassicAutofarm","Running: registering local target (server unconfirmed)")
        -- Preserve the reference contract without inventing random hit speed/damage.
        invoke("Hitboxes","Register",target.Part,root.AssemblyLinearVelocity.Magnitude,0)
        return "Running: attack requested (server unconfirmed)"
    end
    function self:SetToggle(name,enabled)
        if self.Destroyed or (name~="TitanRipper" and name~="SkillAutofarm" and name~="ClassicAutofarm") then return false end
        enabled=enabled==true
        if self.Enabled[name]==enabled then return true end
        self.Enabled[name]=enabled
        state(name,enabled and "Waiting: starting" or "Disabled")
        if name=="SkillAutofarm" then
            if enabled then worker(name,skillTick,0.2) else stop(name) end
        elseif name=="ClassicAutofarm" then
            if enabled then ctx.CancelTeleport();worker(name,classicTick,0.15) else stop(name) end
        end
        updateRipper()
        return true
    end
    function self:CheckShadowBan()
        if self.Destroyed or self.CheckBusy then return false end
        if self.CheckWatchdog then pcall(task.cancel,self.CheckWatchdog);self.CheckWatchdog=nil end
        self.CheckToken=(self.CheckToken or 0)+1
        local token=self.CheckToken
        self.CheckBusy=true;self.CheckResult="Running: requesting account diagnostic"
        self.CheckThread=task.spawn(function()
            local ok,data=pcall(invoke,"Data","Get")
            if self.Destroyed or token~=self.CheckToken then return end
            self.CheckBusy=false;self.CheckThread=nil
            if self.CheckWatchdog then pcall(task.cancel,self.CheckWatchdog);self.CheckWatchdog=nil end
            -- No reliable schema was supplied. Inspect types, never infer a ban verdict.
            if not ok then self.CheckResult="Error: "..tostring(data);ctx.Warn(self.CheckResult)
            elseif type(data)~="table" then self.CheckResult="Waiting: inconclusive / response is "..type(data)
            else
                local count=0
                for key in pairs(data) do if type(key)=="string" and key:lower():find("blacklist",1,true) then count=count+1 end end
                self.CheckResult="Waiting: inconclusive / "..count.." blacklist-like fields; schema unverified"
            end
        end)
        if self.CheckBusy then self.CheckWatchdog=task.spawn(function()
            task.wait(15)
            if self.Destroyed or token~=self.CheckToken or not self.CheckBusy then return end
            self.CheckToken=self.CheckToken+1
            if self.CheckThread then pcall(task.cancel,self.CheckThread);self.CheckThread=nil end
            self.CheckBusy=false
            self.CheckResult="Error: diagnostic timeout; result inconclusive"
            ctx.Warn(self.CheckResult)
        end) end
        return true
    end
    self.Respawn=ctx.Player.CharacterRemoving:Connect(function()
        for part in pairs(effects) do priorCharacterEffects[part]=true end
        mover:Stop();clearRipper()
        -- Cancel in-flight workers on character removal, without changing user's toggles.
        for _,name in ipairs({"Ripper","SkillAutofarm","ClassicAutofarm"}) do stop(name) end
        for name,enabled in pairs(self.Enabled) do if enabled then state(name,"Waiting: respawn") end end
    end)
    self.CharacterAdded=ctx.Player.CharacterAdded:Connect(function()
        if self.Destroyed then return end
        if self.Enabled.SkillAutofarm then worker("SkillAutofarm",skillTick,0.2) end
        if self.Enabled.ClassicAutofarm then worker("ClassicAutofarm",classicTick,0.15) end
        updateRipper()
    end)
    function self:Destroy()
        if self.Destroyed then return end
        self.Destroyed=true
        self.Respawn:Disconnect();self.CharacterAdded:Disconnect()
        for _,name in ipairs({"Ripper","SkillAutofarm","ClassicAutofarm"}) do stop(name) end
        if self.CheckThread then pcall(task.cancel,self.CheckThread) end
        if self.CheckWatchdog then pcall(task.cancel,self.CheckWatchdog) end
        self.CheckBusy=false;mover:Destroy()
    end
    return self
end
return Module

]],
    ["src/games/features/aotr/movement.lua"] = [[
-- Owned tween/hold and character-only noclip. No map edits or game mover writes.
--
-- The farm needs to fly to a nape and the player wants to pass through geometry
-- while doing it, but every change here is character-local (CanCollide on the
-- character's own parts) and is restored on Stop, so leaving the game clean is
-- never dependent on a feature turning itself off first.
local Module={}
function Module.new(context)
    context=context or {}
    local self={Root=nil,Character=nil,Speed=1000,Noclip=true,Collisions={},Destroyed=false}
    local function cancelTween()
        if self.Completed then self.Completed:Disconnect();self.Completed=nil end
        local tween=self.Tween;self.Tween=nil
        if tween then tween:Cancel() end
        self.Arrived=false
    end
    local function restoreCollisions()
        for part,value in pairs(self.Collisions) do
            if part.Parent then pcall(function() part.CanCollide=value end) end
        end
        self.Collisions={}
    end
    local function noclip()
        if not self.Noclip or not self.Character then return end
        for part,value in pairs(self.Collisions) do
            if not part:IsDescendantOf(self.Character) then
                if part.Parent then pcall(function() part.CanCollide=value end) end
                self.Collisions[part]=nil
            end
        end
        for _,part in ipairs(self.Character:GetDescendants()) do
            if part:IsA("BasePart") then
                if self.Collisions[part]==nil then self.Collisions[part]=part.CanCollide end
                part.CanCollide=false
            end
        end
    end
    function self:Stop()
        cancelTween()
        if self.Step then self.Step:Disconnect();self.Step=nil end
        if self.Hold then self.Hold:Destroy();self.Hold=nil end
        restoreCollisions()
        if self.Root and self.Root.Parent then
            if self.Rotation then pcall(function() self.Root.CFrame=CFrame.new(self.Root.Position)*self.Rotation end) end
            pcall(function() self.Root.AssemblyLinearVelocity=self.Velocity end)
            pcall(function() self.Root.AssemblyAngularVelocity=self.AngularVelocity end)
        end
        if self.Humanoid and self.Humanoid.Parent then pcall(function() self.Humanoid.AutoRotate=self.AutoRotate end) end
        self.Humanoid=nil;self.Rotation=nil
        self.Root=nil;self.Character=nil;self.Target=nil;self.TargetModel=nil;self.Goal=nil
    end
    function self:SetSpeed(value)
        value=tonumber(value)
        if self.Destroyed or not value or value~=value or value<50 or value>2000 then return false end
        if self.Speed~=value then self.Speed=value;cancelTween();self.Goal=nil end
        return true
    end
    function self:SetNoclip(value)
        if self.Destroyed then return false end
        self.Noclip=value==true
        if self.Noclip then noclip() else restoreCollisions() end
        return true
    end
    function self:Move(root,target,height,targetModel)
        if self.Destroyed then return false end
        if not root.Parent or not target.Parent then self:Stop();return false end
        if self.Root~=root then
            self:Stop();self.Root=root;self.Character=root.Parent
            self.Velocity=root.AssemblyLinearVelocity;self.AngularVelocity=root.AssemblyAngularVelocity
            self.Rotation=root.CFrame.Rotation
            self.Humanoid=self.Character:FindFirstChildOfClass("Humanoid")
            if self.Humanoid then self.AutoRotate=self.Humanoid.AutoRotate;self.Humanoid.AutoRotate=false end
            self.Hold=Instance.new("BodyVelocity")
            self.Hold.Name="DepHub_AOTR_FarmHold"
            self.Hold.MaxForce=Vector3.new(1000000,1000000,1000000)
            self.Hold.Velocity=Vector3.new(0,0,0);self.Hold.Parent=root
            noclip()
            local run=context.RunService or game:GetService("RunService")
            self.Step=run.Stepped:Connect(function()
                local ok,err=pcall(function()
                    local humanoid=self.Character and self.Character:FindFirstChildOfClass("Humanoid")
                    local targetHumanoid=self.TargetModel and self.TargetModel:FindFirstChildOfClass("Humanoid")
                    if not self.Root or not self.Root.Parent or self.Root.Anchored or not humanoid or humanoid.Health<=0
                        or (self.Target and not self.Target.Parent)
                        or (self.TargetModel and (not self.TargetModel.Parent or not targetHumanoid or targetHumanoid.Health<=0))
                        or (context.Player and context.Player.Character~=self.Character) then self:Stop();return end
                    noclip()
                    self.Root.AssemblyAngularVelocity=Vector3.new(0,0,0)
                end)
                if not ok then self:Stop();if context.Warn then context.Warn("movement: "..tostring(err)) end end
            end)
        end
        noclip()
        self.TargetModel=targetModel
        local goal=target.Position+Vector3.new(0,height,0)
        local distance=(goal-root.Position).Magnitude
        if distance~=distance or distance>10000000 then self:Stop();error("Invalid movement distance") end
        if self.Target==target and self.Goal and (goal-self.Goal.Position).Magnitude<8 then
            if self.Tween or (self.Arrived and distance<4) then return true end
        end
        cancelTween();self.Target=target
        -- The target is directly below the hover point; use a nonparallel up axis.
        self.Goal=CFrame.lookAt(goal,target.Position,Vector3.new(0,0,1))
        if distance<0.5 then root.CFrame=self.Goal;self.Arrived=true;return true end
        local service=context.TweenService or game:GetService("TweenService")
        local tween=service:Create(root,TweenInfo.new(math.max(0.03,distance/self.Speed),Enum.EasingStyle.Linear),{CFrame=self.Goal})
        self.Tween=tween
        self.Completed=tween.Completed:Connect(function(state)
            if self.Tween~=tween then return end
            self.Tween=nil;self.Arrived=state==Enum.PlaybackState.Completed
            if self.Completed then self.Completed:Disconnect();self.Completed=nil end
        end)
        tween:Play()
        return true
    end
    function self:Destroy() if not self.Destroyed then self:Stop();self.Destroyed=true end end
    return self
end
return Module

]],
    ["src/games/features/aotr/properties.lua"] = [[
-- Property layers prevent one feature from restoring over another feature.
--
-- Several AOT:R features write the same property on the same object (the nape's
-- CFrame is touched by both the nape visual and the ripper). Recording the
-- original value once and letting the highest-priority layer win means turning
-- one feature off never clobbers another that is still on.
local Module = {}
function Module.new(warnError)
    local self = {Records={}, Layers={}}
    local function write(object, key, value)
        local ok, err = pcall(function() object[key]=value end)
        if not ok and warnError then warnError("restore "..key..": "..tostring(err)) end
    end
    function self:Original(object, key)
        local record=self.Records[object]
        return record and record[key] and record[key].Value or object[key]
    end
    function self:Refresh()
        for object, record in pairs(self.Records) do
            for key, saved in pairs(record) do
                local value, priority, claimed=nil,-math.huge,false
                for _, layer in pairs(self.Layers) do
                    local values=layer.Values[object]
                    if values and values[key]~=nil and layer.Priority>priority then
                        value,priority,claimed=values[key],layer.Priority,true
                    end
                end
                if claimed then write(object,key,value)
                else
                    local restored=saved.Value
                    if saved.Restore then
                        local ok, result=pcall(saved.Restore)
                        if ok and result~=nil then restored=result end
                    end
                    write(object,key,restored)
                    record[key]=nil
                end
            end
            if next(record)==nil then self.Records[object]=nil end
        end
    end
    function self:Set(owner, values, priority, restorers)
        for object, properties in pairs(values) do
            local record=self.Records[object] or {};self.Records[object]=record
            for key in pairs(properties) do
                if not record[key] then
                    record[key]={Value=object[key],Restore=restorers and restorers[object] and restorers[object][key]}
                end
            end
        end
        self.Layers[owner]={Values=values,Priority=priority or 0}
        self:Refresh()
    end
    function self:Clear(owner) self.Layers[owner]=nil;self:Refresh() end
    function self:Destroy() self.Layers={};self:Refresh() end
    return self
end
return Module

]],
    ["src/games/features/aotr/targets.lua"] = [[
-- Target selection for AOT:R: which titan (and which weakpoint) is live.
--
-- The nape is the kill part; a boss (Attack_Titan) exposes whatever its Marker
-- currently decorates. Returning nil instead of guessing keeps the farm from
-- attacking a part that no longer exists.
local Module={}
local function path(root,...)
    for _,name in ipairs({...}) do root=root and root:FindFirstChild(name) end
    return root
end
Module.Path=path
function Module.Alive(character)
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    local root=path(character,"HumanoidRootPart")
    if not humanoid or humanoid.Health<=0 or not root or not root:IsA("BasePart") then return nil end
    return root,humanoid
end
function Module.Marker(model)
    local marker=path(model,"Marker")
    local hit=path(model,"Hitboxes","Hit")
    if not marker or not hit then return nil end
    local ok,part=pcall(function() return marker.Adornee end)
    if ok and part and part:IsA("BasePart") and part:IsDescendantOf(hit) then return part end
    return nil
end
function Module.Select(workspace,root)
    local folder=path(workspace,"Titans")
    if not folder or not root then return nil,"Waiting: Titans / character" end
    local best,distance=nil,math.huge
    for _,model in ipairs(folder:GetChildren()) do
        local humanoid=model:IsA("Model") and model:FindFirstChildOfClass("Humanoid")
        if humanoid and humanoid.Health>0 then
            -- A boss with no active marker must not fall back to an arbitrary weakpoint.
            local part=model.Name=="Attack_Titan" and Module.Marker(model) or nil
            if model.Name~="Attack_Titan" then part=path(model,"Hitboxes","Hit","Nape") end
            if part and part:IsA("BasePart") then
                local d=(root.Position-part.Position).Magnitude
                if d<distance then best,distance={Model=model,Part=part,Boss=model.Name=="Attack_Titan"},d end
            end
        end
    end
    return best,best and distance or "Waiting: live target / boss marker"
end
return Module

]],
    ["src/games/features/bloxfruits/oss/adapter.lua"] = [[
-- DepHub adapter for the vendored Blox Fruits modules.
--
-- The open-source script ships a main.lua that builds its own window, its own
-- tab list and its own config page. Inside DepHub none of that exists: the
-- DepHub panel owns the screen, so this factory does the wiring main.lua used to
-- do (Core -> modules) but with no presentation at all.
--
-- Order matters: core first, then the feature modules, then the two modules
-- that read UI._currentSea at init (info, shop). Every module is loaded through
-- DepHub's own httpGet so the bundled sources resolve without the network.

local Factory = {}

local ORDER = {"core", "teleport", "combat", "farm", "player", "fruits", "shop", "events", "extras", "info"}

local function readSource(loader, path)
    local ok, source = pcall(loader, path)
    if not ok then return false, tostring(source) end
    if type(source) ~= "string" or #source == 0 then return false, "empty source" end
    return true, source
end

function Factory.new(context)
    context = context or {}
    local vendors = context.Vendors or {}
    local loadSource = context.LoadSource
    if type(loadSource) ~= "function" then return false, "adapter requires LoadSource" end

    -- The vendored modules read their globals (game, task) from the shared
    -- environment, because the loader compiles each one with loadstring and
    -- a chunk has no way to see the loader's locals. Publish the runtime the
    -- same way before any module is compiled. Each target is written under
    -- pcall: executors hand back readonly tables for some of these, and one
    -- failure must not stop the others.
    local runtime = {game = vendors.game, task = vendors.task}
    local published = false
    for _, target in ipairs({
        (type(getgenv) == "function") and select(2, pcall(getgenv)) or nil,
        shared,
        _G
    }) do
        if type(target) == "table" then
            local ok = pcall(function() target.__DEPHUB_OSS_RUNTIME = runtime end)
            published = published or ok
        end
    end
    if not published then return false, "no writable shared environment for __DEPHUB_OSS_RUNTIME" end

    local prefix = context.PathPrefix or "src/games/features/bloxfruits/oss/"
    local State = {Destroyed = false, Modules = {}, Errors = {}, Version = context.Version or "1.0"}
    local log = context.Warn or function() end

    local okUI, uiSource = readSource(loadSource, prefix .. "ui-headless.lua")
    if not okUI then return false, "ui-headless: " .. tostring(uiSource) end
    local uiChunk, uiError = loadstring(uiSource)
    if not uiChunk then return false, "ui-headless: " .. tostring(uiError) end
    local okRunUI, UI = pcall(uiChunk)
    if not okRunUI or type(UI) ~= "table" then return false, "ui-headless: " .. tostring(UI) end
    State.UI = UI
    State.Stats = UI.stats
    State.Notifications = UI.notifications

    for _, name in ipairs(ORDER) do
        local path = prefix .. name .. ".lua"
        local okSource, source = readSource(loadSource, path)
        if not okSource then
            State.Errors[#State.Errors + 1] = path .. ": " .. tostring(source)
            return false, "module failed to load (" .. path .. "): " .. tostring(source)
        end
        local chunk, chunkError = loadstring(source)
        if not chunk then
            State.Errors[#State.Errors + 1] = path .. ": " .. tostring(chunkError)
            return false, "module failed to compile (" .. path .. "): " .. tostring(chunkError)
        end
        local okBuild, module = pcall(chunk, vendors)
        if not okBuild or type(module) ~= "table" then
            State.Errors[#State.Errors + 1] = path .. ": " .. tostring(module)
            return false, "module failed to run (" .. path .. "): " .. tostring(module)
        end
        State.Modules[name] = module
        if name == "core" then State.Core = module end
    end

    local Core = State.Core
    Core.configure({verbose = false})

    UI.build(Core)
    -- Every tab the modules call UI.page() for has to exist before they init,
    -- because addTab is what creates the page object they attach controls to.
    for _, tab in ipairs({
        {"Info", "Player and script info"},
        {"Farm", "Level farm and quests", "Sea1"},
        {"Farm 2", "Level farm and quests", "Sea2"},
        {"Farm 3", "Level farm and quests", "Sea3"},
        {"PVP", "Combat, aura, aimbot, players"},
        {"Teleport", "Move, islands and waypoints"},
        {"Sea", "Sea travel and transitions", "Sea1,Sea2"},
        {"Fruit", "Fruit ESP, collect and dealer"},
        {"Shop", "Buy Sea 1 items", "Sea1"},
        {"Shop 2", "Buy Sea 2 items", "Sea2"},
        {"Shop 3", "Buy Sea 3 items", "Sea3"},
        {"Raids/Events", "Raids, sea events, leviathan", "Sea2,Sea3"},
        {"Extras", "Race V4, awakening, special bosses", "Sea3"},
        {"Player", "Player ESP and mobility"},
        {"Config", "Save and restore settings"},
    }) do
        UI.addTab(tab[1], tab[2], tab[3])
    end

    for _, name in ipairs(ORDER) do
        if name ~= "core" then
            local module = State.Modules[name]
            if type(module.init) == "function" then
                local ok, err = pcall(module.init, Core, UI)
                if not ok then
                    State.Errors[#State.Errors + 1] = name .. ".init: " .. tostring(err)
                    log("Blox Fruits module init failed (" .. name .. "): " .. tostring(err))
                end
            end
        end
    end

    Core.register("ui", UI)
    Core.info("DepHub adapter loaded")

    State.RestoredConfig = false

    -- The sea changes the tab visibility and both info.lua and shop.lua read it
    -- during init, so publish the current sea and expose the hook the backend
    -- uses when the game reports a change.
    local sea = context.Sea or "Sea1"
    pcall(function() UI.setSea(sea) end)
    State.Sea = sea
    if type(UI.onSea) == "function" then pcall(UI.onSea, function(nextSea) State.Sea = nextSea end) end

    function State:SetSea(nextSea)
        if self.Destroyed or type(nextSea) ~= "string" then return false end
        self.Sea = nextSea
        pcall(function() UI.setSea(nextSea) end)
        return true
    end

    function State:GetControls()
        return self.UI and self.UI._controls or {}
    end

    function State:GetControl(key)
        local controls = self:GetControls()
        return controls[key]
    end

    function State:ListControls()
        return self.UI and self.UI._defs or {}
    end

    function State:SetControl(key, value)
        local control = self:GetControl(key)
        if not control or type(control.set) ~= "function" then return false end
        local ok, result = pcall(control.set, value)
        if ok and self.Toggles and control.kind == "toggle" then
            self.Toggles[key] = control.get() == true
        end
        return ok and result ~= false
    end

    function State:GetControlValue(key)
        local control = self:GetControl(key)
        if not control or type(control.get) ~= "function" then return nil end
        local ok, value = pcall(control.get)
        if ok then return value end
        return nil
    end

    function State:GetStatus()
        return {
            Version = self.Version,
            Sea = self.Sea,
            RestoredConfig = self.RestoredConfig,
            Controls = self.UI and #self.UI._defs or 0,
            Modules = self.Modules,
            Errors = self.Errors
        }
    end

    State.Core = Core

    function State:Notify(title, message, duration)
        local text = message
        if text == nil then text = title else text = tostring(title or "DepHub") .. ": " .. tostring(message) end
        pcall(UI.notify, tostring(text), duration)
        return true
    end

    function State:SaveConfig(name)
        local ok, result = pcall(Core.saveNamedConfig, name)
        return ok and result == true
    end

    function State:LoadConfig(name)
        local ok, result = pcall(Core.loadNamedConfig, name)
        return ok and result == true
    end

    function State:ListConfigs()
        local ok, result = pcall(Core.listConfigs)
        if ok and type(result) == "table" then return result end
        return {}
    end

    function State:DeleteConfig(name)
        local ok, result = pcall(Core.deleteNamedConfig, name)
        return ok and result == true
    end

    function State:RenameConfig(from, to)
        local ok, result = pcall(Core.renameNamedConfig, from, to)
        return ok and result == true
    end

    function State:ResetDefaults()
        local ok, result = pcall(Core.resetToDefaults)
        return ok and result == true
    end

    function State:ResetModule(moduleName)
        local ok, result = pcall(Core.resetModule, moduleName)
        return ok and (tonumber(result) or 0)
    end

    State.Config = {
        Save = function(name) return State:SaveConfig(name) end,
        Load = function(name) return State:LoadConfig(name) end,
        List = function() return State:ListConfigs() end,
        Delete = function(name) return State:DeleteConfig(name) end,
        Rename = function(from, to) return State:RenameConfig(from, to) end,
        ResetDefaults = function() return State:ResetDefaults() end,
        ResetModule = function(moduleName) return State:ResetModule(moduleName) end
    }

    function State:Unload()
        if self.Destroyed then return end
        self.Destroyed = true
        pcall(function() Core.unload() end)
        pcall(function() UI.stop() end)
        self.Modules = {}
    end

    function State:Destroy()
        self:Unload()
        if context.Env then
            if context.Env.__DEPHUB_BLOXFRUITS_OSS == self then context.Env.__DEPHUB_BLOXFRUITS_OSS = nil end
            if context.Env.BF == Core then context.Env.BF = nil end
        end
    end

    return State
end

return Factory

]],
    ["src/games/features/bloxfruits/oss/combat.lua"] = [[
local dephub
do
    local function pick(t) return type(t) == "table" and t.__DEPHUB_OSS_RUNTIME or nil end
    dephub = (type(getgenv) == "function" and pick(select(2, pcall(getgenv)))) or pick(shared) or pick(_G)
    if not dephub then error("DepHub OSS runtime missing: __DEPHUB_OSS_RUNTIME was not published", 0) end
end
local game = dephub.game
local task = dephub.task

-- Combat: auto-attack, kill aura, aimbot, bounty hunt.
-- Hits = RegisterAttack + RegisterHit, both need a server-validated hitId (see installCapture).
local Players = game:GetService("Players")
local RS = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local VIM = game:GetService("VirtualInputManager")
local LP = Players.LocalPlayer

local M = {}
M.config = {
    range = 120, delay = 0.15,
    targetPlayers = false, playerRange = 60,
    fast = false,
    auraRange = 60, losCheck = false,
    aimSmooth = 0.15, aimRange = 300, aimPart = "HumanoidRootPart",
    clickInterval = 0.25, skillOrder = "Z X C V F",
    keys = { Z = false, X = false, C = false, V = false, F = false },
    followDist = 6, attack1v1 = false,
    spectate = false, aim = false,
}
M.lastHitId = nil
M._combo, M._hooked = 0, false
M._mobAuto, M._playerAuto, M._aura, M._autoClick, M._follow = false, false, false, false, false
M._wasSpectate = false

M.bounty = {
    noFriends = false, noCup = false,
    safePct = 20,
    invisKen = false,
    chatKill = false, chatMsg = "gg",
    maxTime = 20,
    team = "Both",
    method = "Nearest",
    ignore = {},
}
M._bountyOn, M._noStunOn = false, false
M._bountySkip = {}

local function net()
    local mods = RS:FindFirstChild("Modules")
    local n = mods and mods:FindFirstChild("Net")
    if not n then return end
    return n:FindFirstChild("RE/RegisterAttack"), n:FindFirstChild("RE/RegisterHit")
end
local function effDelay() return M.config.fast and 0.08 or M.config.delay end

-- "Z X C V F" -> {"Z","X","C","V","F"}. Any key token is accepted so a user can
-- reorder the rotation; unknown tokens are ignored by pressKey (Enum.KeyCode nil).
local function parseSkillOrder(text)
    local list = {}
    for token in tostring(text or ""):gmatch("%S+") do
        local key = token:upper()
        if M.config.keys[key] ~= nil then list[#list + 1] = key end
    end
    if #list == 0 then list = { "Z", "X", "C", "V", "F" } end
    return list
end

-- "Aurora, bob123" -> {aurora=true, bob123=true}. Comma or whitespace separated,
-- lowercased; used by the bounty ignore list (matches name or display name).
local function parseIgnoreList(text)
    local set = {}
    for token in tostring(text or ""):gmatch("[^,%s]+") do
        local name = token:lower()
        if name ~= "" then set[name] = true end
    end
    return set
end

function M.hrp() local ch = LP and LP.Character; return ch and ch:FindFirstChild("HumanoidRootPart") end

local function isFishingRod(t)
    if not t then return false end
    local tip = t.ToolTip
    return (tip and (tostring(tip):find("Fishing") or tostring(tip):find("Rod"))) or t.Name:find("Rod") ~= nil
end
-- A fishing rod hijacks the RegisterAttack hook, so hits never land: unequip it before attacking.
local function ensureNotRod()
    local ch = LP.Character
    local eq = ch and ch:FindFirstChildOfClass("Tool")
    if eq and isFishingRod(eq) then
        local hum = ch:FindFirstChildOfClass("Humanoid")
        if hum then pcall(function() hum:UnequipTools() end) end
    end
end

local function losClear(fromPos, part, ignore)
    local p = RaycastParams.new()
    p.FilterType = Enum.RaycastFilterType.Exclude
    p.FilterDescendantsInstances = { LP.Character, ignore }
    return workspace:Raycast(fromPos, part.Position - fromPos, p) == nil
end

-- Steal a valid hitId from the game's own RegisterHit call. A forged id is rejected on fresh
-- accounts, so we hook __namecall and read the real one the client sends.
function M.installCapture()
    if M._hooked then return end
    if not (hookmetamethod and getnamecallmethod and checkcaller and newcclosure) then
        if M._core then M._core.warn("no hook API: hitId capture unavailable") end
        return
    end
    local _, RegisterHit = net()
    M._capturing = true
    local old
    old = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
        if M._capturing and not checkcaller() and getnamecallmethod() == "FireServer" and self == RegisterHit then
            local a = table.pack(...)
            if a[4] ~= nil then M.lastHitId = a[4]
            elseif a.n == 1 and type(a[1]) == "string" then M.lastHitId = a[1] end
        end
        return old(self, ...)
    end))
    M._hooked = true
end

local function isRaidChip(t) return t.Name:find("Microchip") ~= nil end
local function reequipWeapon()
    local ch = LP.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    local tool = ch:FindFirstChildOfClass("Tool")
    if tool and (isFishingRod(tool) or isRaidChip(tool)) then tool = nil end
    if not tool then
        local bp = LP:FindFirstChild("Backpack")
        if bp then for _, t in ipairs(bp:GetChildren()) do
            if t:IsA("Tool") and not isFishingRod(t) and not isRaidChip(t) then tool = t; break end
        end end
    end
    if tool then
        pcall(function() hum:UnequipTools() end)
        task.wait(0.15)
        pcall(function() hum:EquipTool(tool) end)
    end
end
function M.setupHitId()
    M.installCapture()
    task.spawn(function()
        ensureNotRod()
        reequipWeapon()
        task.wait(0.5)
        if M.lastHitId then
            if M._core then M._core.info("hitId captured", tostring(M.lastHitId)) end
            return
        end
        local _, RegisterHit = net()
        if RegisterHit then
            local id = tostring(LP.UserId):sub(2, 4) .. tostring(coroutine.running()):sub(11, 15)
            pcall(function() RegisterHit:FireServer(id) end)
            M.lastHitId = id
            if M._core then M._core.warn("hitId fallback generated", tostring(id)) end
        end
    end)
end

function M.nearest(range)
    local hrp, folder = M.hrp(), workspace:FindFirstChild("Enemies")
    if not hrp or not folder then return end
    local best, bestD
    for _, e in ipairs(folder:GetChildren()) do
        local hum = e:FindFirstChildOfClass("Humanoid")
        local part = e:FindFirstChild("HumanoidRootPart") or e.PrimaryPart
        if hum and hum.Health > 0 and part then
            local d = (part.Position - hrp.Position).Magnitude
            if d <= range and (not bestD or d < bestD) then best, bestD = e, d end
        end
    end
    return best
end

function M.nearestAny(range)
    local h = M.hrp(); if not h then return end
    local best, bestD
    for _, d in ipairs(workspace:GetDescendants()) do
        if d:IsA("Humanoid") and d.Health > 0 then
            local model = d.Parent
            if model and model ~= LP.Character and not Players:GetPlayerFromCharacter(model) then
                local part = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
                if part then
                    local dd = (part.Position - h.Position).Magnitude
                    if dd <= (range or 1e9) and (not bestD or dd < bestD) then best, bestD = model, dd end
                end
            end
        end
    end
    return best
end

function M.nearestPlayer(range)
    local h = M.hrp()
    if not h then return end
    local best, bestD
    for _, p in ipairs(Players:GetPlayers()) do
        local ch = p ~= LP and p.Character
        local ph = ch and ch:FindFirstChild("HumanoidRootPart")
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if ph and hum and hum.Health > 0 then
            local d = (ph.Position - h.Position).Magnitude
            if (not range or d <= range) and (not bestD or d < bestD) then best, bestD = ch, d end
        end
    end
    return best
end

function M.attackOnce(enemy)
    ensureNotRod()
    local RegisterAttack, RegisterHit = net()
    if not (RegisterAttack and RegisterHit and enemy) then return end
    local part = enemy:FindFirstChild("HumanoidRootPart") or enemy.PrimaryPart
        or enemy:FindFirstChildWhichIsA("BasePart")
    if not part then return end
    M._combo = (M._combo % 4) + 1
    RegisterAttack:FireServer(0.4, M._combo)
    RegisterHit:FireServer(part, {}, nil, M.lastHitId)   -- 4th arg = captured hitId; without it the hit is ignored
end

function M.attackMany(list)
    ensureNotRod()
    local RegisterAttack, RegisterHit = net()
    if not (RegisterAttack and RegisterHit) or #list == 0 then return end
    M._combo = (M._combo % 4) + 1
    RegisterAttack:FireServer(0.4, M._combo)
    for _, e in ipairs(list) do
        local part = e:FindFirstChild("HumanoidRootPart") or e.PrimaryPart
        if part then RegisterHit:FireServer(part, {}, nil, M.lastHitId) end
    end
end

function M.playersInRange(range)
    local h, list = M.hrp(), {}
    if not h then return list end
    for _, p in ipairs(Players:GetPlayers()) do
        local ch = p ~= LP and p.Character
        local ph = ch and ch:FindFirstChild("HumanoidRootPart")
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if ph and hum and hum.Health > 0 and (ph.Position - h.Position).Magnitude <= range then
            list[#list + 1] = ch
        end
    end
    return list
end
function M.attackPlayersInRange(range)
    for _, ch in ipairs(M.playersInRange(range)) do M.attackOnce(ch) end
end

function M.setMobAuto(on)
    M._mobAuto = on and true or false
    if M._mobAuto and M._core then
        M._core.spawn(function()
            while M._mobAuto do
                M.attackOnce(M.nearest(M.config.range))
                task.wait(effDelay())
            end
        end)
    end
end

function M.setPlayerAuto(on)
    M._playerAuto = on and true or false
    if M._playerAuto and M._core then
        M._core.spawn(function()
            while M._playerAuto do
                M.attackPlayersInRange(M.config.playerRange)
                task.wait(effDelay())
            end
        end)
    end
end

function M.setAura(on)
    M._aura = on and true or false
    if M._aura and M._core then
        M._core.spawn(function()
            while M._aura do
                local h, folder = M.hrp(), workspace:FindFirstChild("Enemies")
                if h and folder then
                    local list = {}
                    for _, e in ipairs(folder:GetChildren()) do
                        local hum = e:FindFirstChildOfClass("Humanoid")
                        local part = e:FindFirstChild("HumanoidRootPart") or e.PrimaryPart
                        if hum and hum.Health > 0 and part and (part.Position - h.Position).Magnitude <= M.config.auraRange then
                            if not M.config.losCheck or losClear(h.Position, part, e) then list[#list + 1] = e end
                        end
                    end
                    M.attackMany(list)
                end
                if M.config.targetPlayers then M.attackPlayersInRange(M.config.auraRange) end
                task.wait(effDelay())
            end
        end)
    end
end

function M.pressKey(name)
    local kc = Enum.KeyCode[name]
    if not kc then return end
    pcall(function()
        VIM:SendKeyEvent(true, kc, false, game)
        task.wait(0.03)
        VIM:SendKeyEvent(false, kc, false, game)
    end)
end
function M.setAutoClick(on)
    M._autoClick = on and true or false
    if M._autoClick and M._core then
        M._core.spawn(function()
            while M._autoClick do
                -- Fire keys in the configured order, not pairs() order: a hash
                -- table has no order, so the rotation used to come out different
                -- every session (and a combo needs a stable sequence).
                for _, k in ipairs(M._skillOrder or { "Z", "X", "C", "V", "F" }) do
                    if not M._autoClick then break end
                    if M.config.keys[k] then M.pressKey(k) end
                end
                task.wait(M.config.clickInterval)
            end
        end)
    end
end

function M.setFollow(on)
    M._follow = on and true or false
    if M._follow and M._core then
        M._core.spawn(function()
            while M._follow do
                local tp = M._core.modules.teleport
                local ch = M.nearestPlayer()
                local ph = ch and ch:FindFirstChild("HumanoidRootPart")
                if tp and ph then tp.go(ph.Position + ph.CFrame.LookVector * -M.config.followDist) end
                if M.config.attack1v1 and ch then M.attackOnce(ch) end
                task.wait(0.3)
            end
        end)
    end
end

local function myHealthPct()
    local ch = LP.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    if hum and hum.MaxHealth > 0 then return hum.Health / hum.MaxHealth * 100 end
    return 100
end
local function holdingCup(ch)
    for _, t in ipairs(ch:GetChildren()) do if t:IsA("Tool") and t.Name == "Cup" then return true end end
    return false
end
-- A player on the ignore list is never targeted, matched on display name or
-- username (lowercased), so a user can paste either one.
local function isIgnored(p)
    local list = M.bounty.ignore
    if not list or not next(list) then return false end
    local name = p.Name:lower()
    local dname = (p.DisplayName or ""):lower()
    return list[name] == true or list[dname] == true
end
local function bountyValid(p)
    if p == LP then return false end
    local ch = p.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    local ph = ch and ch:FindFirstChild("HumanoidRootPart")
    if not (hum and ph and hum.Health > 0) then return false end
    if isIgnored(p) then return false end
    if M.bounty.noFriends then
        local ok, f = pcall(function() return LP:IsFriendsWith(p.UserId) end)
        if ok and f then return false end
    end
    if M.bounty.noCup and holdingCup(ch) then return false end
    if M.bounty.team ~= "Both" and p.Team and p.Team.Name:lower():find(M.bounty.team:lower()) == nil then return false end
    local sk = M._bountySkip[p.UserId]
    if sk and sk > os.clock() then return false end
    return true
end
local function pickBounty()
    local h = M.hrp(); if not h then return end
    local best, bestScore
    for _, p in ipairs(Players:GetPlayers()) do
        if bountyValid(p) then
            local ch = p.Character
            local ph, hum = ch:FindFirstChild("HumanoidRootPart"), ch:FindFirstChildOfClass("Humanoid")
            local score = (M.bounty.method == "Lowest HP") and hum.Health or (ph.Position - h.Position).Magnitude
            if not bestScore or score < bestScore then best, bestScore = p, score end
        end
    end
    return best
end
function M.chat(msg)
    pcall(function()
        local TCS = game:GetService("TextChatService")
        if TCS.ChatVersion == Enum.ChatVersion.TextChatService then
            TCS.TextChannels.RBXGeneral:SendAsync(msg)
        else
            RS.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(msg, "All")
        end
    end)
end
function M.setNoStun(on)
    M._noStunOn = on and true or false
    if M._noStunOn and M._core then
        M._core.spawn(function()
            while M._noStunOn do
                local ch = LP.Character
                local hum = ch and ch:FindFirstChildOfClass("Humanoid")
                if ch and hum then
                    if hum.PlatformStand then hum.PlatformStand = false end
                    for _, a in ipairs({ "Stun", "Stunned" }) do
                        if ch:GetAttribute(a) then ch:SetAttribute(a, false) end
                    end
                end
                task.wait(0.1)
            end
        end)
    end
end
function M.setBounty(on)
    M._bountyOn = on and true or false
    if not (M._bountyOn and M._core) then return end
    M._core.spawn(function()
        local tp = M._core.modules.teleport
        while M._bountyOn do
            if myHealthPct() < M.bounty.safePct then
                local h = M.hrp()
                if tp and h then tp.go(h.Position + Vector3.new(0, 220, 0)) end
                if M._ui then M._ui.notify("Safe zone: low HP, retreating") end
                task.wait(1.2)
            else
                local target = pickBounty()
                if not target then task.wait(0.5) else
                    local start = os.clock()
                    while M._bountyOn and (os.clock() - start) < M.bounty.maxTime do
                        if myHealthPct() < M.bounty.safePct then break end
                        local ch = target.Character
                        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
                        local ph = ch and ch:FindFirstChild("HumanoidRootPart")
                        if not (ch and hum and ph and hum.Health > 0) then
                            if M.bounty.chatKill then M.chat(M.bounty.chatMsg) end
                            break
                        end
                        local off = M.config.followDist
                        local dest = ph.Position + ph.CFrame.LookVector * -off + Vector3.new(0, M.bounty.invisKen and 4 or 0, 0)
                        if tp then tp.go(dest) end
                        M.attackOnce(ch)
                        task.wait(effDelay())
                    end
                    if os.clock() - start >= M.bounty.maxTime then M._bountySkip[target.UserId] = os.clock() + 8 end
                end
            end
        end
    end)
end

function M.stop()
    M._mobAuto, M._playerAuto, M._aura, M._autoClick, M._follow, M._capturing = false, false, false, false, false, false
    M._bountyOn, M._noStunOn = false, false
    M.config.aim, M.config.spectate = false, false
    local cam = workspace.CurrentCamera
    local myHum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
    if cam and myHum then cam.CameraSubject = myHum end
end

function M.init(Core, UI)
    M._core = Core
    M.installCapture()
    M._skillOrder = parseSkillOrder(M.config.skillOrder)

    Core.track(RunService.RenderStepped:Connect(function()
        local cam = workspace.CurrentCamera
        if not cam then return end
        if M.config.aim then
            local ch = M.nearestPlayer(M.config.aimRange)
            local ph = ch and (ch:FindFirstChild(M.config.aimPart) or ch:FindFirstChild("HumanoidRootPart"))
            if ph then
                cam.CFrame = cam.CFrame:Lerp(CFrame.lookAt(cam.CFrame.Position, ph.Position), M.config.aimSmooth)
            end
        end
        if M.config.spectate then
            local ch = M.nearestPlayer()
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            if hum then cam.CameraSubject = hum; M._wasSpectate = true end
        elseif M._wasSpectate then
            local myHum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
            if myHum then cam.CameraSubject = myHum end
            M._wasSpectate = false
        end
    end))

    local page = UI.page("PVP")
    UI.toggle(page, "Auto attack players", "Attack the nearby players", false, function(s) M.setPlayerAuto(s) end)
    UI.slider(page, "Player range", "Player detection radius", 10, 200, M.config.playerRange, function(v) M.config.playerRange = v end)
    UI.toggle(page, "Fast attack", "Minimum delay between hits", M.config.fast, function(s) M.config.fast = s end)
    UI.toggle(page, "Attack players while farming", "Hit nearby players during auto-farm too", false, function(s) M.config.targetPlayers = s end)

    UI.section(page, "KILL AURA")
    UI.toggle(page, "Kill aura", "Hit everything in range (mobs + players)", false, function(s) M.setAura(s) end)
    UI.slider(page, "Aura range", "Radius", 10, 200, M.config.auraRange, function(v) M.config.auraRange = v end)
    UI.toggle(page, "Line of sight", "Only hit visible targets", M.config.losCheck, function(s) M.config.losCheck = s end)

    UI.section(page, "AIMBOT")
    UI.toggle(page, "Aimbot", "Lock camera on the nearest player", false, function(s) M.config.aim = s end)
    UI.slider(page, "Smoothness", "Lower = smoother", 3, 100, math.floor(M.config.aimSmooth * 100), function(v) M.config.aimSmooth = v / 100 end)
    UI.slider(page, "Aimbot range", "Only lock onto players within this radius", 20, 1000, M.config.aimRange, function(v) M.config.aimRange = v end)
    UI.dropdown(page, "Aim part", "Body part to aim at", { "HumanoidRootPart", "Head", "UpperTorso", "LowerTorso" }, function(s) M.config.aimPart = s end)

    UI.section(page, "AUTO SKILLS")
    UI.toggle(page, "Auto skills", "Auto-press the skill keys", false, function(s) M.setAutoClick(s) end)
    for _, k in ipairs({ "Z", "X", "C", "V", "F" }) do
        UI.toggle(page, "Key " .. k, "Include " .. k .. " in the rotation", M.config.keys[k], function(s) M.config.keys[k] = s end)
    end
    UI.textbox(page, "Skill order (default: Z X C V F)", function(t)
        M.config.skillOrder = (t ~= "" and t) or "Z X C V F"
        M._skillOrder = parseSkillOrder(M.config.skillOrder)
    end)
    UI.slider(page, "Skill interval (ms)", "Delay between key series", 100, 1000, math.floor(M.config.clickInterval * 1000), function(v) M.config.clickInterval = v / 1000 end)

    UI.section(page, "PLAYERS")
    UI.toggle(page, "Follow nearest", "Teleport onto the nearest player", false, function(s) M.setFollow(s) end)
    UI.toggle(page, "1v1 (attack target)", "Attack the followed player", false, function(s) M.config.attack1v1 = s end)
    UI.toggle(page, "Spectate nearest", "Camera on the nearest player", false, function(s) M.config.spectate = s end)
    UI.button(page, "Show captured hit id", "hitId from your last real M1", function()
