        local token=self.CounterToken local characterToken=self.CharacterToken
        task.delay(self.Config.CounterDelay,function()
            if self.Destroyed or not self.Enabled or not self.Config.M1AfterBlock or token~=self.CounterToken or characterToken~=self.CharacterToken then return end
            if self:_isLocalAttacking() then self.DebugInfo.SuppressedCounters=self.DebugInfo.SuppressedCounters+1 return end
            if not tracker or tracker.Destroyed or not tracker.Root or not tracker.Root.Parent then return end
            local myRoot=self:_localRoot() if not myRoot then return end local distance=(tracker.Root.Position-myRoot.Position).Magnitude if distance>self.Config.CounterRange then return end
            if self:_leftClickOnce() then self.DebugInfo.Counters=self.DebugInfo.Counters+1 self:_debug("counter M1: "..tostring(player and player.Name or "unknown")) end
        end)
    end
    function self:_releaseBlock(reason,suppressCounter)
        if not self.BlockActive then self.BlockUntil=0 self.BlockSource=nil self.BlockTargetPlayer=nil self.BlockTargetTracker=nil if suppressCounter then self.CounterPending=false end self:_restoreCamera() return false end
        self:_communicate("KeyRelease") self.BlockActive=false self.BlockUntil=0 self.BlockSource=nil self.DebugInfo.Releases=self.DebugInfo.Releases+1 self:_restoreCamera()
        if suppressCounter then self.CounterPending=false else self:_queueCounter() end
        self.BlockTargetPlayer=nil self.BlockTargetTracker=nil if reason then self:_debug("block release: "..tostring(reason)) end return true
    end
    function self:_pressBlock(duration,source,reason,player,tracker,animationId,metrics)
        if self.Destroyed or not self.Enabled or not self:_localAlive() then return false,false end
        local now=os_clock() local hold=clamp(tonumber(duration) or 0.15,0.05,3)
        self.BlockUntil=math_max(self.BlockUntil,now+hold) self.BlockSource=source or self.BlockSource or "unknown" self.BlockTargetPlayer=player or self.BlockTargetPlayer self.BlockTargetTracker=tracker or self.BlockTargetTracker
        self.CounterPending=self.Config.M1AfterBlock==true self.DebugInfo.LastReason=tostring(reason or source or "unknown") self.DebugInfo.LastAnimation=animationId and tostring(animationId) or "none" self.DebugInfo.LastPlayer=player and player.Name or "none"
        if metrics then self.DebugInfo.LastDistance=metrics.Distance or 0 self.DebugInfo.LastPredictedDistance=metrics.PredictedDistance or metrics.Distance or 0 self.DebugInfo.LastFacing=metrics.Facing or 0 self.DebugInfo.LastClosingSpeed=metrics.ClosingSpeed or 0 if metrics.Predicted then self.DebugInfo.PredictionBlocks=self.DebugInfo.PredictionBlocks+1 end end
        if tracker then self:_beginCameraLock(player,tracker) end
        if self.BlockActive then return true,false end
        -- Release an already-held M1 before requesting F; do not restart it automatically.
        self:_communicate("LeftClickRelease",true)
        if not self:_communicate("KeyPress") then self.BlockUntil=0 self.BlockSource=nil self.BlockTargetPlayer=nil self.BlockTargetTracker=nil self.CounterPending=false self:_restoreCamera() return false,false end
        self.BlockActive=true self.DebugInfo.Blocks=self.DebugInfo.Blocks+1 return true,true
    end
    function self:_trackerReady(tracker)
        if not tracker or not tracker.Character or not tracker.Character.Parent or not tracker.Root or not tracker.Root.Parent or not tracker.Humanoid or tracker.Humanoid.Health<=0 then return false end
        local live=Workspace:FindFirstChild("Live") self.DebugInfo.Live=live and "ready" or "missing" return live~=nil and tracker.Character.Parent==live
    end
    function self:_activeCount(tracker,set) local count=0 for id in pairs(set) do if (tracker.ActiveIds[id] or 0)>0 then count=count+1 end end return count end
    function self:_checkDashCombo(player,tracker)
        if not self.Config.DashBlock or self:_activeCount(tracker,comboIds)<2 then return false end
        local myRoot=self:_localRoot() if not myRoot then return false end local metrics=self:_threatMetrics(tracker,myRoot,self.Config.SpecialRange,false,true)
        if not metrics or not metrics.Pass then return false end self:_pressBlock(0.7,"dash","combo/dash",player,tracker,nil,metrics) return true
    end
    function self:_handleM1(player,tracker,reason)
        if not self.Config.M1Block or not self:_trackerReady(tracker) then return false end
        local myRoot=self:_localRoot() if not myRoot then return false end local metrics=self:_threatMetrics(tracker,myRoot,self.Config.NormalRange,false,true)
        if not metrics or not metrics.Pass then return false end local ok=self:_pressBlock(0.18,"m1",reason or "M1ing",player,tracker,nil,metrics) if ok then tracker.InsideLast=true end return ok
    end
    function self:_logUnknown(player,tracker,animationId)
        if not self.Config.UnknownLogger or knownIds[animationId] or self.UnknownSeen[animationId] then return end
        local myRoot=self:_localRoot() if not myRoot or not tracker or not tracker.Root or not tracker.Root.Parent then return end
        local distance=(tracker.Root.Position-myRoot.Position).Magnitude if distance>self.Config.SkillRange then return end
        self.UnknownSeen[animationId]=true self.DebugInfo.UnknownAnimations=self.DebugInfo.UnknownAnimations+1
        print("[DepHub TSB][UNKNOWN] player="..tostring(player and player.Name or "unknown").." id="..tostring(animationId).." distance="..string.format("%.1f",distance))
    end
    function self:_handleAnimation(player,tracker,animationId)
        if not self:_trackerReady(tracker) then return end self:_logUnknown(player,tracker,animationId) if self:_checkDashCombo(player,tracker) then return end
        local myRoot=self:_localRoot() if not myRoot then return end
        if normalIds[animationId] and self.Config.M1Block then local metrics=self:_threatMetrics(tracker,myRoot,self.Config.NormalRange,false,true) if metrics and metrics.Pass then self:_pressBlock(0.18,"m1","M1 animation",player,tracker,animationId,metrics) end return end
        if specialIds[animationId] and self.Config.DashBlock then local metrics=self:_threatMetrics(tracker,myRoot,self.Config.SpecialRange,false,true) if metrics and metrics.Pass then self:_pressBlock(1,"dash","special/dash",player,tracker,animationId,metrics) end return end
        if self.Config.SkillBlock and skillIds[animationId] then local metrics=self:_threatMetrics(tracker,myRoot,self.Config.SkillRange,false,false) if metrics and metrics.Pass then self:_pressBlock(self.Config.SkillHold,"skill","skill",player,tracker,animationId,metrics) end end
    end
    function self:_registerTrack(player,tracker,track,process)
        if not tracker or not track or tracker.TrackIds[track] then return end local id=getAnimationId(track) if not id then return end
        tracker.TrackIds[track]=id tracker.ActiveIds[id]=(tracker.ActiveIds[id] or 0)+1 self.DebugInfo.AnimationEvents=self.DebugInfo.AnimationEvents+1
        local connection
        connection=track.Stopped:Connect(function()
            if tracker.Destroyed then return end local stored=tracker.TrackIds[track] tracker.TrackIds[track]=nil tracker.TrackConnections[track]=nil if connection then pcall(connection.Disconnect,connection) connection=nil end
            if stored then local count=(tracker.ActiveIds[stored] or 1)-1 if count<=0 then tracker.ActiveIds[stored]=nil else tracker.ActiveIds[stored]=count end end
        end)
        tracker.TrackConnections[track]=connection if process~=false then self:_handleAnimation(player,tracker,id) end
    end
    function self:_destroyTracker(binding)
        local tracker=binding and binding.Tracker if not tracker then return end binding.Tracker=nil tracker.Destroyed=true disconnectAll(tracker.Connections)
        for track,connection in pairs(tracker.TrackConnections) do tracker.TrackConnections[track]=nil if connection then pcall(connection.Disconnect,connection) end end
    end
    function self:_attachTracker(player,binding,character,humanoid,root,animator)
        if self.Destroyed or not self.Enabled or not binding or binding.Character~=character then return end self:_destroyTracker(binding)
        local tracker={Destroyed=false,Character=character,Humanoid=humanoid,Root=root,Animator=animator,M1ing=character:FindFirstChild("M1ing",true)~=nil,InsideLast=false,ActiveIds={},TrackIds=setmetatable({},{__mode="k"}),TrackConnections=setmetatable({},{__mode="k"}),Connections={}}
        binding.Tracker=tracker
