    function self:SetShowDetectionBox(value) self.Config.ShowDetectionBox=value==true if self.Config.M1Block and self.Enabled then self:_ensureDetectionBox() end return true end
    function self:SetDebug(value) self.Config.Debug=value==true return true end
    function self:SetNormalRange(value) value=tonumber(value) if not value then return false end self.Config.NormalRange=clamp(value,2,30) return true end
    function self:SetSpecialRange(value) value=tonumber(value) if not value then return false end self.Config.SpecialRange=clamp(value,5,80) return true end
    function self:SetSkillRange(value) value=tonumber(value) if not value then return false end self.Config.SkillRange=clamp(value,5,80) return true end
